************************************************************************
*                                                                      *
      subroutine ttimereg(ncol,m,nl,lt,np,nr,mr,ne,nt,kr,eb,tb,tr,
     &                    trEVENT)
*                                                                      *
*       time tally in region mesh                                      *
*       last modified by K.Niita on 2014/09/02                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)
      common /paraj/  mstz(300), parz(300)

      common /mathzn/ mathz, mathn, jcoll, kcoll
!$OMP THREADPRIVATE(/mathzn/)
*-----------------------------------------------------------------------

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)

      common /tall82/ itcnth(9,itlmax)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   tb(nt+1)
      dimension   tr(np,ne,nt,nr,2)
      dimension   trEVENT(np,ne,nt,nr)        !OBINATA(2012.9.18): as Ct
      real(8),allocatable,save:: tr0(:,:,:,:) !OBINATA(2012.9.18): as C

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension ncntt(3)
      dimension dmpd(30)

*-----------------------------------------------------------------------

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

*-----------------------------------------------------------------------
      integer idmpomp !FURUTA20150427
      common /idmpomp0/idmpomp !FURUTA20150427
*-----------------------------------------------------------------------

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.18): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,:,1) = tr(:,:,:,:,1) + trEVENT(:,:,:,:)
             tr(:,:,:,:,2) = tr(:,:,:,:,2) + trEVENT(:,:,:,:) ** 2

! sumover
             call ttimereg_sumover(m,1,
     &                   np,  ne, nt,  nr, trEVENT)


           end if

           trEVENT(:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.18): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nt,nr) )
             tr0(:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (ttimereg_crit_ist1)
             tr0(:,:,:,:) = tr0(:,:,:,:) + trEVENT(:,:,:,:)
!$OMP END CRITICAL (ttimereg_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,:,1) = tr(:,:,:,:,1) + tr0(:,:,:,:) / maxcas
             tr(:,:,:,:,2) = tr(:,:,:,:,2)
     &                     + ( tr0(:,:,:,:) / maxcas ) ** 2

! sumover
             call ttimereg_sumover(m,maxcas,
     &                   np,  ne, nt,  nr, tr0)

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        out put : check of ncol
*-----------------------------------------------------------------------

         if( ncol .eq. 11 .or. ncol .eq. 12 .or.
     &     (  (  ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &           jcoll .eq. 2 .and. itout(m) .eq. 4) ) then

            if( itout(m) .eq. 2 .and. ncol .ne. 11 ) return
            if( itout(m) .eq. 3 .and. ncol .ne. 12 ) return

               iccol = 0

               npart = 1

               ipart = ityp
               kpart = ktyp
               jpart = jtyp

               xpart = xc(ibkxc+no,ipomp+1)
               ypart = yc(ibkyc+no,ipomp+1)
               zpart = zc(ibkzc+no,ipomp+1)
               upart = u(ibku+no,ipomp+1)
               vpart = v(ibkv+no,ipomp+1)
               wpart = w(ibkw+no,ipomp+1)
               epart = ec(ibkec+no,ipomp+1)
               tpart = abs(tc(ibktc+no,ipomp+1))
               sxpat = spx(ibkspx+no,ipomp+1)
               sypat = spy(ibkspy+no,ipomp+1)
               szpat = spz(ibkspz+no,ipomp+1)
               nzpat = ctyp
               nname = name(ibknam+no,ipomp+1)
               tlw   = oldwt

               ncntt(1) = ncnt(ibknct+1,no,ipomp+1)
               ncntt(2) = ncnt(ibknct+2,no,ipomp+1)
               ncntt(3) = ncnt(ibknct+3,no,ipomp+1)

         else if( ncol .eq. 13 .or. ncol .eq. 14 ) then

            if( itout(m) .eq. 3 ) return
            if( itout(m) .eq. 4 ) return
            if( nclsts .le. 0 ) return

               iccol = 1

               npart = nclsts

               ncntt(1) = jcount(1,1)
               ncntt(2) = jcount(2,1)
               ncntt(3) = jcount(3,1)

         else

            return

         end if

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncntt(i) .lt. itcnt(i*2+2,m) .or.
     &                ncntt(i) .gt. itcnt(i*2+3,m) ) return

               end if

            end do

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

                  jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir1 = ii

*-----------------------------------------------------------------------
*        do loop for particles
*-----------------------------------------------------------------------

         do 200 j = 1, npart

*-----------------------------------------------------------------------

            if( iccol .eq. 1 ) then

                  if( jclusts(4,j) .ge. 0 ) goto 200

                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = ichgf(ipart,kpart)

                  epart = qclusts(7,j)
                  tlw   = qclusts(8,j)
                  tpart = abs(qclusts(9,j))
                  xpart = qclusts(10,j)
                  ypart = qclusts(11,j)
                  zpart = qclusts(12,j)

                  upart = qclusts(1,j)
                  vpart = qclusts(2,j)
                  wpart = qclusts(3,j)

                  sxpat = spx(ibkspx+no,ipomp+1)
                  sypat = spy(ibkspy+no,ipomp+1)
                  szpat = spz(ibkspz+no,ipomp+1)
                  nzpat = jclusts(5,j)
                  nname = name(ibknam+no,ipomp+1)

            end if

*-----------------------------------------------------------------------

      if( iMeVperu.eq.1 .and. ipart.ge.15 .and. ipart.le.19 ) then
           ebm = kpart - kpart / 1000000 * 1000000
      else
           ebm = 1.d0
      end if

*-----------------------------------------------------------------------
*           check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ipart,kpart,jpart,ipn,ips)

               if( ipn .eq. 0 ) goto 200

*-----------------------------------------------------------------------
*           check of energy
*-----------------------------------------------------------------------

               if( epart .lt. eb(1)*ebm ) goto 200
               if( epart .ge. eb(ne+1)*ebm ) goto 200

*-----------------------------------------------------------------------
*           energy
*-----------------------------------------------------------------------

            do i = 1, ne

               if( epart .ge. eb(i)*ebm .and.
     &             epart .lt. eb(i+1)*ebm ) goto 30

            end do

   30          ie1 = i

*-----------------------------------------------------------------------
*           check of time
*-----------------------------------------------------------------------

               if( tpart .lt. tb(1) ) goto 200
               if( tpart .ge. tb(nt+1) ) goto 200

*-----------------------------------------------------------------------
*           time
*-----------------------------------------------------------------------

            do i = 1, nt

               if( tpart .ge. tb(i) .and.
     &             tpart .lt. tb(i+1) ) goto 40

            end do

   40          it1 = i

*-----------------------------------------------------------------------
*           tally
*-----------------------------------------------------------------------

            do ip = 1, ipn

               trEVENT(ips(ip),ie1,it1,ir1) =
     &         trEVENT(ips(ip),ie1,it1,ir1) + tlw

            end do

*-----------------------------------------------------------------------
*        dump data on file
*-----------------------------------------------------------------------

         if( itmdp(m,0) .ne. 0 ) then
               dmpd(1)  = dble( kpart )
               dmpd(2)  = xpart
               dmpd(3)  = ypart
               dmpd(4)  = zpart
               dmpd(5)  = upart
               dmpd(6)  = vpart
               dmpd(7)  = wpart
               dmpd(8)  = epart
               dmpd(9)  = tlw
               dmpd(10) = tpart
               dmpd(11) = ncntt(1)
               dmpd(12) = ncntt(2)
               dmpd(13) = ncntt(3)
               dmpd(14) = sxpat
               dmpd(15) = sypat
               dmpd(16) = szpat
               dmpd(17) = nname
               dmpd(18) = nocas
               dmpd(19) = nobch
               dmpd(20) = no
               dmpd(21) = nzpat

               if( ipart .ge. 15 )
     &         dmpd(8) = dmpd(8) / ibryf(ipart,kpart)

            if(idmpomp.ne.0)then       !FURUTA20150427
             call writeompfile(m,dmpd) !FURUTA20150427
            else                       !FURUTA20150427

             if( itmdp(m,0) .gt. 0 ) then

               write(itmdf(m))
     &         ( dmpd(itmdp(m,k)), k = 1, abs( itmdp(m,0) ) )

              else

               write(itmdf(m),'(30(1p1d24.15))')
     &         ( dmpd(itmdp(m,k)), k = 1, abs( itmdp(m,0) ) )

              end if

            endif !FURUTA20150427

         end if

*-----------------------------------------------------------------------

  200    continue

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine ptimereg(m,np,nr,mr,ne,nt,kr,eb,tb,tr,
     &                    nvl,ivl,rvl,
     &                    nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the time tally in region mesh                           *
*       last modified by K.Niita on 2005/08/15                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)
      common /tall49/ itglt(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31
*-----------------------------------------------------------------------

      common /volreg/ dvol(kvlmax)
      common /regdc/ idrg(kvlmax), idgr(kvmmax)

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   tb(nt+1)
      dimension   ew(ne)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   tw(nt)
      dimension   tr(np,ne,nt,nr,2)
      dimension   ivl(nvl)
      dimension   rvl(nvl)

      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

      dimension tott(np,2) ! frtati 2021/10/05 6 -> np

      character hsunit(4)*28

      data hsunit / '[1/source]              ',
     &              '[1/nsec/source]         ',
     &              '[1/nsec/cm^3/source]    ',
     &              '[1/nsec/cm^3/MeV/source]'/

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      character cha*1
      data cha /"'"/

      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31

      character rpa*1
      data rpa /'}'/
      character yen*1

      include 'samepage_include/samepage000.inc'

      include 'samepage_include/samepage001.inc'

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------

      if ( iMeVperu.eq. 1 ) then
         hsunit(4) = '[1/nsec/cm^3/(MeV/n)/source]'
      end if

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            neg = ne
            ntg = nt

         else

            npg = 1
            neg = 1
            ntg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1 : /source
*                    = 2 : /nsec/source
*                    = 3 : /nsec/cm^3/source
*                    = 4 : /nsec/cm^3/MeV/source
*-----------------------------------------------------------------------

            vl_sum = sum(vl(:))

            if( itunt(m) .eq. 1 ) then

               do i = 1, nt

                  tw(i) = 1.d+0

               end do
               tw_sum = 1.0d0

            else if( itunt(m) .ne. 1 ) then

               do i = 1, nt

                  tw(i) = tb(i+1) - tb(i)

               end do
               tw_sum = tb(nt+1) - tb(1)

            end if

*-----------------------------------------------------------------------

            if( itunt(m) .ne. 4 ) then

               do i = 1, ne

                  ew(i) = 1.d+0

               end do
               ew_sum = 1.d+0

            else if( itunt(m) .eq. 4 ) then

               do i = 1, ne

                  ew(i) = eb(i+1) - eb(i)

               end do
               ew_sum = eb(ne+1) - eb(1)

            end if

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 ir = 1, nr
               do 101 ie = 1, ne
               do 101 it = 1, nt
               do 101 ip = 1, np

                  if( tr(ip,ie,it,ir,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ip,ie,it,ir,1) / ew(ie) / tw(it)

                     if( itunt(m) .ge. 3 ) fmaxfc = fmaxfc / vl(ir)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            do 100 ir = 1, nr
            do 100 ie = 1, ne
            do 100 it = 1, nt
            do 100 ip = 1, np

               if( tr(ip,ie,it,ir,1) .gt. 0.d0 ) then

                  cc = abs(rtfac(m)/facmax(m)) / ew(ie) / tw(it)

                  if( itunt(m) .ge. 3 ) cc = cc / vl(ir)

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,it,ir,1),
     &                            tr(ip,ie,it,ir,2),
     &                            cc)

                  tr(ip,ie,it,ir,1) = Xa
                  tr(ip,ie,it,ir,2) = sigx
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ip,ie,it,ir,1) .gt. cmax )
     &                             cmax = tr(ip,ie,it,ir,1)

                  if( tr(ip,ie,it,ir,1) .lt. cmin )
     &                             cmin = tr(ip,ie,it,ir,1)

               else

                  isdz = 1
                  tr(ip,ie,it,ir,2) = 0.0

               end if

! sumover
               fact_in = abs(rtfac(m)/facmax(m))
               if( itunt(m) .ge. 3 ) then
                 call ptimereg_sumover_stdev(0,m,ip,ie,it,ir,
     &              fact_in,ew(ie),tw(it),vl(ir),ew_sum,tw_sum,vl_sum)
               else
                 call ptimereg_sumover_stdev(0,m,ip,ie,it,ir,
     &              fact_in,ew(ie),tw(it),1.0d0,ew_sum,tw_sum,1.0d0)
               endif


  100       continue

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

         end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

         if( igsh .ne. 0 .and.
     &     ( itaxs(m,iax) .lt. 7 .or. itrsh(m) .eq. 0 ) ) goto 900

         if( itmdp(m,0) .eq. 0 ) then

            if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &           .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

               call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &              nobch,maxbch,npe)

            else

               fname = ctfln(m,iax)

            end if

         else

            if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &           .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

               call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &              nobch,maxbch,npe)

            else

               fname = ctfln(m,iax)(1:itfll(m,iax))

            end if

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call ttimech(iot,m,iax,1)

*-----------------------------------------------------------------------

      include 'samepage_include/samepage002_petr.inc'
      include 'samepage_include/samepagechp_petr.inc'
      include 'samepage_include/samepageseti.inc'

*-----------------------------------------------------------------------
*        energy axis
*-----------------------------------------------------------------------

               inum = 0

         if( itaxs(m,iax) .eq. 1 ) then

            do iri = 1, nr, nrstepi
            do iti = 1, nt, ntstepi
            do ipi = 1, np, npstepi
               ir = iri
               it = iti
               ip = ipi

               inum = inum + 1

               ireg = lr(ir)

                  write(iot,'(/"#",78("-"))')

