     &                     "  tmin  &=&",1pe13.4," [nsec]"/
     &                     "  tmax  &=&",1pe13.4," [nsec]"/
     &                     "  y     &=&",1pe13.4," [cm]"/
     &                     "  part. &=&   ",a8/
     &                     "e:")')
     &                     yen, eb(ie), eb(ie+1),
     &                     tb(it), tb(it+1),
     &                     yval, chq(ip)
                  end if

            end if

*-----------------------------------------------------------------------

      if( inolg .eq. 1 .and. igsh .eq. 0 .and.
     &    cmin .gt. 0.0 .and. cmax .gt. cmin ) then

         write(iot,'(/"#",78("-"))')
         write(iot,'("z: xorg[-1.03/0.05]"/
     &               "p: form[c1] xfac[c2] afac[c5] nosp notf")')

               write(iot,'( "p: xmin(",1p1g14.7,") xmax(",1p1g14.7,
     &                       ")")') zmin, zmax

               write(iot,'( "p: ymin(",1p1g14.7,") ymax(",1p1g14.7,
     &                       ")")') xmin, xmax

      end if

*-----------------------------------------------------------------------

            end do
            end do
            end do
            end do

*-----------------------------------------------------------------------

         end if

            call prestart(m,iot) !OBINATA(2012.9.18)

            close(iot)

         if( iteps(m) .ne. 0 ) then

            open(iot, file = fname, status = 'unknown' )
            call a_angel(idasa,fname)

         end if

  900 continue

*-----------------------------------------------------------------------
      deallocate( ixyz )
cnais 2023/01/31
      include 'samepage_include/samepage999.inc'

      return
      end


************************************************************************
*                                                                      *
      subroutine ttimerz(ncol,m,nl,lt,np,nr,nz,ne,nt,rm,zm,eb,tb,tr,
     &                   trEVENT,itrmax,itrmin)
*                                                                      *
*       time tally in r-z scoring mesh                                 *
*       last modified by K.Niita on 2014/09/02                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
*-----------------------------------------------------------------------

      implicit double precision( a-h, o-z )

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /paraj/  mstz(300), parz(300)

      common /mathzn/ mathz, mathn, jcoll, kcoll
!$OMP THREADPRIVATE(/mathzn/)
*-----------------------------------------------------------------------

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)

      common /tall82/ itcnth(9,itlmax)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension rm(nr+1)
      dimension zm(nz+1)
      dimension eb(ne+1)
      dimension tb(nt+1)
      dimension tr(np,ne,nt,nr,nz,2)
      dimension trEVENT(np,ne,nt,nr,nz)         !OBINATA(2012.9.18): as Ct
      real(8),allocatable,save:: tr0(:,:,:,:,:) !OBINATA(2012.9.18): as C
      dimension itrmax(5),itrmin(5)

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension ncntt(3)
      dimension dmpd(30)

*-----------------------------------------------------------------------

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
      integer idmpomp !FURUTA20150427
      common /idmpomp0/idmpomp !FURUTA20150427
*-----------------------------------------------------------------------

      if (istdev .eq. 2) then
        call readitrminmax5(itrmin,itrmax,(/np,ne,nt,nr,nz/),
     &                      mnp,mne,mnt,mnr,mnz,
     &                      mxp,mxe,mxt,mxr,mxz)
      endif

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.18): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             do iz = mnz,mxz
             do ir = mnr,mxr
             do it = mnt,mxt
             do ie = mne,mxe
               tr(:,ie,it,ir,iz,1) = tr(:,ie,it,ir,iz,1)
     &                             + trEVENT(:,ie,it,ir,iz)
               tr(:,ie,it,ir,iz,2) = tr(:,ie,it,ir,iz,2)
     &                             + trEVENT(:,ie,it,ir,iz) ** 2
             enddo
             enddo
             enddo
             enddo

! sumover
             call ttimerz_sumover(m,1,
     &                   np,  ne, nt,  nr, nz, trEVENT)


           end if

           do iz = mnz,mxz
           do ir = mnr,mxr
           do it = mnt,mxt
           do ie = mne,mxe
             trEVENT(:,ie,it,ir,iz) = 0
           enddo
           enddo
           enddo
           enddo

           call resetitrminmax(itrmin,itrmax,5,(/np,ne,nt,nr,nz/))

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.18): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nt,nr,nz) )
             tr0(:,:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (ttimerz_crit_ist1)
             tr0(:,:,:,:,:) = tr0(:,:,:,:,:) + trEVENT(:,:,:,:,:)
!$OMP END CRITICAL (ttimerz_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,:,:,1) = tr(:,:,:,:,:,1) + tr0(:,:,:,:,:) / maxcas
             tr(:,:,:,:,:,2) = tr(:,:,:,:,:,2)
     &                     + ( tr0(:,:,:,:,:) / maxcas ) ** 2

! sumover
             call ttimerz_sumover(m,maxcas,
     &                   np,  ne, nt,  nr, nz, tr0)

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:,:) = 0

         end if


*-----------------------------------------------------------------------
*        out put : check of ncol
*-----------------------------------------------------------------------

         if( ncol .eq. 11 .or. ncol .eq. 12 .or.
     &     (  (  ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &           jcoll .eq. 2 .and. itout(m) .eq. 4) ) then

            if( itout(m) .eq. 2 .and. ncol .ne. 11 ) return
            if( itout(m) .eq. 3 .and. ncol .ne. 12 ) return

               iccol = 0

               npart = 1

               ipart = ityp
               kpart = ktyp
               jpart = jtyp

               xpart = xc(ibkxc+no,ipomp+1)
               ypart = yc(ibkyc+no,ipomp+1)
               zpart = zc(ibkzc+no,ipomp+1)
               upart = u(ibku+no,ipomp+1)
               vpart = v(ibkv+no,ipomp+1)
               wpart = w(ibkw+no,ipomp+1)
               epart = ec(ibkec+no,ipomp+1)
               tpart = abs(tc(ibktc+no,ipomp+1))
               sxpat = spx(ibkspx+no,ipomp+1)
               sypat = spy(ibkspy+no,ipomp+1)
               szpat = spz(ibkspz+no,ipomp+1)
               nzpat = ctyp
               nname = name(ibknam+no,ipomp+1)
               tlw   = oldwt

               ncntt(1) = ncnt(ibknct+1,no,ipomp+1)
               ncntt(2) = ncnt(ibknct+2,no,ipomp+1)
               ncntt(3) = ncnt(ibknct+3,no,ipomp+1)

         else if( ncol .eq. 13 .or. ncol .eq. 14 ) then

            if( itout(m) .eq. 3 ) return
            if( itout(m) .eq. 4 ) return
            if( nclsts .le. 0 ) return

               iccol = 1

               npart = nclsts

               ncntt(1) = jcount(1,1)
               ncntt(2) = jcount(2,1)
               ncntt(3) = jcount(3,1)

         else

            return

         end if

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncntt(i) .lt. itcnt(i*2+2,m) .or.
     &                ncntt(i) .gt. itcnt(i*2+3,m) ) return

               end if

            end do

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        do loop for particles
*-----------------------------------------------------------------------

         do 100 j = 1, npart

*-----------------------------------------------------------------------

            if( iccol .eq. 1 ) then

                  if( jclusts(4,j) .ge. 0 ) goto 100

                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = ichgf(ipart,kpart)

                  epart = qclusts(7,j)
                  tpart = abs(qclusts(9,j))
                  tlw   = qclusts(8,j)

                  xpart = qclusts(10,j)
                  ypart = qclusts(11,j)
                  zpart = qclusts(12,j)

                  upart = qclusts(1,j)
                  vpart = qclusts(2,j)
                  wpart = qclusts(3,j)

                  sxpat = spx(ibkspx+no,ipomp+1)
                  sypat = spy(ibkspy+no,ipomp+1)
                  szpat = spz(ibkspz+no,ipomp+1)
                  nzpat = jclusts(5,j)
                  nname = name(ibknam+no,ipomp+1)

            end if

*-----------------------------------------------------------------------

      if( iMeVperu.eq.1 .and. ipart.ge.15 .and. ipart.le.19 ) then
           ebm = kpart - kpart / 1000000 * 1000000
      else
           ebm = 1.d0
      end if

*-----------------------------------------------------------------------
*           transform positions
*-----------------------------------------------------------------------

            call trnsxx(xpart,ypart,zpart,
     &                  xxc,yyc,zzc,itmtr(m,4))

*-----------------------------------------------------------------------
*           check z mesh and r mesh region
*-----------------------------------------------------------------------

            if(  zzc .lt. zm(1) ) goto 100
            if(  zzc .ge. zm(nz+1) ) goto 100

               x0 = rtrx0(m)
               y0 = rtry0(m)

               dis0 = sqrt( (  xxc - x0 )**2
     &                    + (  yyc - y0 )**2 )

            if( dis0 .lt. rm(1) ) goto 100
            if( dis0 .ge. rm(nr + 1) ) goto 100

*-----------------------------------------------------------------------
*           z-position
*-----------------------------------------------------------------------

               do i = 1, nz

                  if( zzc .ge. zm(i) .and.
     &                zzc .lt. zm(i+1) ) goto 38

               end do

   38          iz1 = i

*-----------------------------------------------------------------------
*           r-position
*-----------------------------------------------------------------------

               do i = 1, nr

                  if( dis0 .ge. rm(i) .and.
     &                dis0 .lt. rm(i+1) ) goto 47

               end do

   47          ir1 = i

*-----------------------------------------------------------------------
*           check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ipart,kpart,jpart,ipn,ips)

               if( ipn .eq. 0 ) goto 100

*-----------------------------------------------------------------------
*           check of energy
*-----------------------------------------------------------------------

               if( epart .lt. eb(1)*ebm ) goto 100
               if( epart .ge. eb(ne+1)*ebm ) goto 100

*-----------------------------------------------------------------------
*           energy
*-----------------------------------------------------------------------

            do i = 1, ne

               if( epart .ge. eb(i)*ebm .and.
     &             epart .lt. eb(i+1)*ebm ) goto 30

            end do

   30          ie1 = i

*-----------------------------------------------------------------------
*           check of time
*-----------------------------------------------------------------------

               if( tpart .lt. tb(1) ) goto 100
               if( tpart .ge. tb(nt+1) ) goto 100

*-----------------------------------------------------------------------
*           time
*-----------------------------------------------------------------------

            do i = 1, nt

               if( tpart .ge. tb(i) .and.
     &             tpart .lt. tb(i+1) ) goto 40

            end do

   40          it1 = i

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

               do ip = 1, ipn

                  trEVENT(ips(ip),ie1,it1,ir1,iz1) =
     &            trEVENT(ips(ip),ie1,it1,ir1,iz1) + tlw

               end do

               call setitrminmax(itrmin,itrmax,2,5,
     &                           (/ie1,it1,ir1,iz1/))

*-----------------------------------------------------------------------
*        dump data on file
*-----------------------------------------------------------------------

         if( itmdp(m,0) .ne. 0 ) then
               dmpd(1)  = dble( kpart )
               dmpd(2)  = xpart
               dmpd(3)  = ypart
               dmpd(4)  = zpart
               dmpd(5)  = upart
               dmpd(6)  = vpart
               dmpd(7)  = wpart
               dmpd(8)  = epart
               dmpd(9)  = tlw
               dmpd(10) = tpart
               dmpd(11) = ncntt(1)
               dmpd(12) = ncntt(2)
               dmpd(13) = ncntt(3)
               dmpd(14) = sxpat
               dmpd(15) = sypat
               dmpd(16) = szpat
               dmpd(17) = nname
               dmpd(18) = nocas
               dmpd(19) = nobch
               dmpd(20) = no
               dmpd(21) = nzpat

               if( ipart .ge. 15 )
     &         dmpd(8) = dmpd(8) / ibryf(ipart,kpart)

            if(idmpomp.ne.0)then       !FURUTA20150427
             call writeompfile(m,dmpd) !FURUTA20150427
            else                       !FURUTA20150427

             if( itmdp(m,0) .gt. 0 ) then

               write(itmdf(m))
     &         ( dmpd(itmdp(m,k)), k = 1, abs( itmdp(m,0) ) )

              else

               write(itmdf(m),'(30(1p1d24.15))')
     &         ( dmpd(itmdp(m,k)), k = 1, abs( itmdp(m,0) ) )

              end if

            endif !FURUTA20150427

         end if

*-----------------------------------------------------------------------

  100    continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine ptimerz(m,np,nr,nz,ne,nt,rm,zm,eb,tb,tr,idasa)
*                                                                      *
*       output r-z scoring mesh time tally                             *
*       last modified by K.Niita on 2005/08/15                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /tcntl/  icntl, inucr

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   rm(nr+1)
      dimension   zm(nz+1)
      dimension   eb(ne+1)
      dimension   tb(nt+1)
      dimension   ew(ne)
      dimension   tw(nt)
      dimension   tr(np,ne,nt,nr,nz,2)

*-----------------------------------------------------------------------

      dimension tott(np,2) ! frtati 2021/10/05 6 -> np

      character hsunit(4)*28

      data hsunit / '[1/source]              ',
     &              '[1/nsec/source]         ',
     &              '[1/nsec/cm^3/source]    ',
     &              '[1/nsec/cm^3/MeV/source]'/

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      character cha*1
      data cha /"'"/

      character dc2*4
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31

*-----------------------------------------------------------------------

      data pi/3.14159265d+0/

      character rpa*1
      data rpa /'}'/
      character yen*1

      real(8),allocatable :: vl_r(:),vl_z(:)

      include 'samepage_include/samepage000.inc'

*-----------------------------------------------------------------------
*        set mesh volume
*-----------------------------------------------------------------------

                  vl(ir,iz) = pi * ( rm(ir+1)**2 - rm(ir)**2 )
     &                           * ( zm(iz+1) - zm(iz) )

*-----------------------------------------------------------------------

      include 'samepage_include/samepage001.inc'

! sumover
      allocate (vl_r(nz),vl_z(nr))
      if( itunt(m) .le. 2 ) then
         vl_r(:) = 1.0d0
         vl_z(:) = 1.0d0
      else if( itunt(m) .ge. 3 ) then
         vl_r(:) = 0.0d0
         vl_z(:) = 0.0d0
         do iz = 1, nz
           do ir = 1, nr
             vl_r(iz) = vl_r(iz) + vl(ir,iz)
             vl_z(ir) = vl_z(ir) + vl(ir,iz)
           enddo
         enddo
       end if

      yen  = char(92)
      igsh = 0
      tott = 0.d0

      if ( iMeVperu.eq. 1 ) then
         hsunit(4) = '[1/nsec/cm^3/(MeV/n)/source]'
      end if

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*        c1 : nomalization for source
*-----------------------------------------------------------------------

            if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

               c1 = 1.0d+0 / rsouin

            else

               c1 = 0d0

            end if

*-----------------------------------------------------------------------
*           itunt(m) = 1 : /source
*                    = 2 : /nsec/source
*                    = 3 : /nsec/cm^3/source
*                    = 4 : /nsec/cm^3/MeV/source
*-----------------------------------------------------------------------

            if( itunt(m) .eq. 1 ) then

               do i = 1, nt

                  tw(i) = 1.d+0

               end do
               tw_sum = 1.0d0

            else if( itunt(m) .ne. 1 ) then

               do i = 1, nt

                  tw(i) = tb(i+1) - tb(i)

               end do
               tw_sum = tb(nt+1) - tb(1)

            end if

*-----------------------------------------------------------------------

            if( itunt(m) .ne. 4 ) then

               do i = 1, ne

                  ew(i) = 1.d+0

               end do
               ew_sum = 1.0d0

            else if( itunt(m) .eq. 4 ) then

               do i = 1, ne

                  ew(i) = eb(i+1) - eb(i)

               end do
               ew_sum = eb(ne+1) - eb(1)

            end if

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*-----------------------------------------------------------------------

                  cmax = 0.0
                  cmin = 1.e+33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 iz = 1, nz
               do 101 ir = 1, nr
               do 101 ie = 1, ne
               do 101 it = 1, nt
               do 101 ip = 1, np

                  if( tr(ip,ie,it,ir,iz,1) .gt. 0.d0 ) then

                     if( itunt(m) .le. 2 ) then

                        vm = 1.d+0

                     else if( itunt(m) .ge. 3 ) then

                        vm = vl(ir,iz)

                     end if

                     fmaxfc = tr(ip,ie,it,ir,iz,1)
     &                                      / vm / ew(ie) / tw(it)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            do 100 iz = 1, nz
            do 100 ir = 1, nr
