     &            "#  iz =",i3/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                        inum, ir, rm(ir), rm(ir+nrstepi),
     &                        iz, zm(iz), zm(iz+nzstepi)
               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &            "#  it =",i3,/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     it, tb(it), tb(it+ntstepi)
               end if

               if( itaxl(m) .eq. 0 ) then

                if ( iMeVperu.eq. 1 ) then
                  write(iot,'(/"x: Energy [MeV/n]")')
                else
                  write(iot,'(/"x: Energy [MeV]")')
                end if

               else

                  write(iot,'(/"x: ",200a1)')
