*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 6 ) then

               inum = 0

            do iei = 1, ne, nestepi
            do izi = 1, nz, nzstepi
            do iti = 1, nt, ntstepi
            do ipi = 1, np, npstepi
               ie = iei
               iz = izi
               it = iti
               ip = ipi

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

