     &    igsh .eq. 0 ) then

         write(iot,'(/"#",78("-"))')
         write(iot,'("z: xorg[-1.03/0.05]"/
     &               "p: form[c1] xfac[c2] afac[c5] nosp notf")')

               write(iot,'( "p: xmin(",1p1g14.7,") xmax(",1p1g14.7,
     &                       ")")') zmin, zmax

               write(iot,'( "p: ymin(",1p1g14.7,") ymax(",1p1g14.7,
     &                       ")")') rmin, rmax

      end if

*-----------------------------------------------------------------------

            end do
            end do
            end do

*-----------------------------------------------------------------------

         end if

*-----------------------------------------------------------------------

            call prestart(m,iot) !OBINATA(2012.9.25)

            close(iot)

         if( iteps(m) .ne. 0 ) then

            open(iot, file = fname, status = 'unknown' )
            call a_angel(idasa,fname)

         end if

        end do

      end do

*-----------------------------------------------------------------------
      include 'samepage_include/samepage999.inc'

      deallocate (vl_r,vl_z)

      return
      end


************************************************************************
*                                                                      *
      subroutine tstarxyz(ncol,m,np,nx,ny,nz,ne,nt,
     &                    nm,mt,nl,lt,xm,ym,zm,eb,tb,tr,trEVENT,
     &                    itrmax,itrmin)
*                                                                      *
*       star density tally in xyz scoring mesh                         *
*       last modified by K.Niita on 2011/05/17                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*                                                                      *
*        jcoll : =  0, nothing happen                                  *
*                =  1, Hydrogen collisions                             *
*                =  2, Particle Decays                                 *
*                =  3, Elastic collisions                              *
*                =  4, High Energy Nuclear collisions                  *
*                =  5, Heavy Ion reactions                             *
*                =  6, Neutron reactions by data                       *
*                =  7, Photon reactions by data                        *
*                =  8, Electron reactions by data                      *
*                =  9, P,d,a, and photo-nuclear reactions by data      *
*                = 10, Neutron event mode                              *
*                = 11, Delta Ray production                            *
*                = 12, Muon atomic interaction                         *
*                = 13, Photon by EGS5                                  *
*                = 14, Electron by EGS5                                *
*                = 15, Photon photonuclear interaction                 *
*                = 16, Negative muon captured by nucleon               *
*                = 17, Muon photonuclear interaction                   *
*                = 18, Electron recoil by track strcuture mode         *
*                = 19, Muon pair production (photon -> mu+ mu-)        *
*                = 20, User defined interaction                        *
*                                                                      *
*        kcoll : =  0, normal                                          *
*                =  1, high energy fission                             *
*                =  2, high energy absorption                          *
*                =  3, low energy n elastic                            *
*                =  4, low energy n non-elastic                        *
*                =  5, low energy n fission                            *
*                =  6, low energy n absorption                         *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
*-----------------------------------------------------------------------

      implicit double precision( a-h, o-z )

*-----------------------------------------------------------------------

      include 'param.inc'
      include 'param00.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /mathzn/ mathz, mathn, jcoll, kcoll
!$OMP THREADPRIVATE(/mathzn/)
      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

      common /trstar/ itrstar
!$OMP THREADPRIVATE(/trstar/)

      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
*-----------------------------------------------------------------------

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall12/ itman(itlmax), itmat(itlmax), itmct(itlmax),
     &                itnun(itlmax), itnuc(itlmax),
     &                itndz(itlmax), itndn(itlmax),
     &                itnkz(itlmax), itnkn(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)

      common /tall82/ itcnth(9,itlmax)

*-----------------------------------------------------------------------

      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      dimension mt(nm)
      dimension lt(nl)
      dimension xm(nx+1)
      dimension ym(ny+1)
      dimension zm(nz+1)
      dimension eb(ne+1)
      dimension tb(nt+1)
      dimension tr(np,ne,nt,nx,ny,nz,2)
      dimension trEVENT(np,ne,nt,nx,ny,nz)        !OBINATA(2012.9.25): as Ct
      real(8),allocatable,save:: tr0(:,:,:,:,:,:) !OBINATA(2012.9.25): as C
      dimension itrmax(6),itrmin(6)

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension dmpd(30)

*-----------------------------------------------------------------------

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

*-----------------------------------------------------------------------
      integer idmpomp !FURUTA20150427
      common /idmpomp0/idmpomp !FURUTA20150427
*-----------------------------------------------------------------------
      common /tstara/ atmrc(10,8)      ! Ogawa 2023/7/18, (10,7) -> (10,8) for plasmon
!$OMP THREADPRIVATE(/tstara/)
      dimension ipsa(itmxpt)    ! S.Abe 2022/06/29, 6 -> itmxpt

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

      dimension ldo(2,6)

*-----------------------------------------------------------------------

      if (istdev .eq. 2) then
        call readitrminmax6(itrmin,itrmax,(/np,ne,nt,nx,ny,nz/),
     &                      mnp,mne,mnt,mnx,mny,mnz,
     &                      mxp,mxe,mxt,mxx,mxy,mxz)
      endif

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.25): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then


             do iz = mnz,mxz
             do iy = mny,mxy
             do ix = mnx,mxx
             do it = mnt,mxt
             do ie = mne,mxe
               tr(:,ie,it,ix,iy,iz,1) = tr(:,ie,it,ix,iy,iz,1)
     &                                + trEVENT(:,ie,it,ix,iy,iz)
               tr(:,ie,it,ix,iy,iz,2) = tr(:,ie,it,ix,iy,iz,2)
     &                                + trEVENT(:,ie,it,ix,iy,iz) ** 2
             enddo
             enddo
             enddo
             enddo
             enddo

! sumover
           ldo(1,1) = 1
           ldo(2,1) = np
           ldo(1,2) = mne
           ldo(2,2) = mxe
           ldo(1,3) = mnt
           ldo(2,3) = mxt
           ldo(1,4) = mnx
           ldo(2,4) = mxx
           ldo(1,5) = mny
           ldo(2,5) = mxy
           ldo(1,6) = mnz
           ldo(2,6) = mxz
           call tstarxyz_sumover(m,1,
     &                   np,  ne, nt,  nx, ny, nz, trEVENT,ldo)



           end if

           do iz = mnz,mxz
           do iy = mny,mxy
           do ix = mnx,mxx
           do it = mnt,mxt
           do ie = mne,mxe
             trEVENT(:,ie,it,ix,iy,iz) = 0
           enddo
           enddo
           enddo
           enddo
           enddo

           call resetitrminmax(itrmin,itrmax,6,(/np,ne,ne,nx,ny,nz/))

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.25): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nt,nx,ny,nz) )
             tr0(:,:,:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (tstarxyz_crit_ist1)
             tr0(:,:,:,:,:,:) = tr0(:,:,:,:,:,:) + trEVENT(:,:,:,:,:,:)
!$OMP END CRITICAL (tstarxyz_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,:,:,:,1) = tr(:,:,:,:,:,:,1)
     &                         + tr0(:,:,:,:,:,:) / maxcas
             tr(:,:,:,:,:,:,2) = tr(:,:,:,:,:,:,2)
     &                     + ( tr0(:,:,:,:,:,:) / maxcas ) ** 2
! sumover
           ldo(1,1) = 1
           ldo(2,1) = np
           ldo(1,2) = 1
           ldo(2,2) = ne
           ldo(1,3) = 1
           ldo(2,3) = nt
           ldo(1,4) = 1
           ldo(2,4) = nx
           ldo(1,5) = 1
           ldo(2,5) = ny
           ldo(1,6) = 1
           ldo(2,6) = nz
           call tstarxyz_sumover(m,maxcas,
     &                   np,  ne, nt,  nx, ny, nz, tr0,ldo)
             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        out put : check of ncol and jcoll
*-----------------------------------------------------------------------

         if( ncol .ne. 13 .and. ncol .ne. 14 ) return

cABE 2018/02/15, reconstruct
*-----------------------------------------------------------------------

      sum20 = atmrc(2,4)+atmrc(3,4)                                     ! knockelec
      sum21 = atmrc(1,1)+atmrc(2,1)+atmrc(3,1)+atmrc(4,1)               ! atmflu
      sum22 = atmrc(1,2)+atmrc(2,2)+atmrc(3,2)                          ! auger
      sum23 = atmrc(2,3)+atmrc(3,3)+atmrc(4,3)+atmrc(5,3)+atmrc(2,5)    ! brems
      sum24 = atmrc(1,3)                                                ! photoelec
      sum25 = atmrc(1,4)                                                ! compton
      sum26 = atmrc(1,5)+atmrc(4,5)+atmrc(5,5)                          ! pairprod
      sum27 = atmrc(3,5)                                                ! annih

      sum30 = atmrc(6,1)+atmrc(7,1)                                     ! ets_elas
      sum31 = atmrc(6,2)+atmrc(7,2)                                     ! ets_ioniz
      sum32 = atmrc(6,3)+atmrc(7,3)                                     ! ets_e-exc
      sum33 = atmrc(6,4)+atmrc(7,4)                                     ! ets_dea
      sum34 = atmrc(6,5)+atmrc(7,5)                                     ! ets_v-exc
      sum35 = atmrc(6,6)+atmrc(7,6)                                     ! ets_p-exc
      sum36 = atmrc(6,7)+atmrc(7,7)                                     ! ets_r-exc
      sum37 = atmrc(6,8)+atmrc(7,8)                                     ! ets_plasmon
      sum38 = atmrc(6,2)+atmrc(6,3)+atmrc(7,2)+atmrc(7,3)               ! ets_ioniz_e-exc
      sum39 = sum30 + sum31 + sum32 + sum33 + sum34 + sum35 + sum36     ! ets_hit

      sum40 = atmrc(8,1)+atmrc(9,1)                                     ! kurbuc_elas
      sum41 = atmrc(8,2)+atmrc(9,2)                                     ! kurbuc_ioniz
      sum42 = atmrc(8,3)+atmrc(9,3)                                     ! kurbuc_e-exc
      sum43 = atmrc(8,4)+atmrc(9,4)                                     ! kurbuc_e-cap
      sum44 = atmrc(8,5)+atmrc(9,5)                                     ! kurbuc_e-stp
      sum48 = atmrc(8,2)+atmrc(9,2)+atmrc(8,3)+atmrc(9,3)
     .                             +atmrc(8,4)+atmrc(9,4)               ! kurbuc_ioniz_e-exc_e-cap
      sum49 = sum40 + sum41 + sum42 + sum43 + sum44                     ! kurbuc_hit

      sum50 = atmrc(10,1)                                               ! its_elas   itsart-Rutherford
      sum51 = atmrc(10,2)                                               ! its_ioniz   itsart-ionization
      sum52 = atmrc(10,3)                                               ! its_e-exc   itsart-electronic excitation
      sum58 = atmrc(10,2) + atmrc(10,3) + atmrc(10,4)                   ! its_ioniz_e-exc_e-cap
      sum59 = sum(atmrc(10,1:7))                                        ! its_hit

      sum96 = sum31 + sum41 + sum51 + sum44                             ! ts_w (ioniz + e-stp)
      sum97 = sum31 + sum41 + sum51                                     ! ts_ioniz
      sum98 = sum38 + sum48 + sum58 + sum33                             ! ts_bio (ioniz + e-exc + e-cap + dea)
      sum99 = sum39 + sum49 + sum59                                     ! ts_hit

      sum09 = sum20+sum21+sum22+sum23+sum24+sum25+sum26+sum27           ! atomic
     &       +sum99

*----------------------------------------------------------------

      sumxx = atmrc(1,6)+atmrc(2,6)+atmrc(3,6)                          ! raylei scat and mscat
      if( sum09 .le. 0.d0 .and. sumxx .gt. 0.d0 ) return
      if( (jcoll.eq.13 .or .jcoll.eq.14) .and. sum09.le.0.d0 ) return   ! return when tinel=0 in EGS5

*-----------------------------------------------------------------------

      do i = 1, 1

         ichk = 1

         if( itout(m) .eq. 1 ) exit                                     ! all
         if( itout(m) .eq. 2 .and.                                      ! decay
     &       ityp .ne. 13 .and. jcoll .eq. 2 ) exit
         if( itout(m) .eq. 3 .and.                                      ! elastic
     &       ( jcoll .eq. 3  .or. kcoll .eq. 3 ) ) exit
         if( itout(m) .eq. 4 .and.                                      ! nuclear
     &       kcoll .ne. 3 .and.
     &       ( jcoll .eq. 1  .or. jcoll .eq. 4  .or. jcoll .eq. 5  .or.
     &         jcoll .eq. 6 .or. jcoll .eq. 9 .or.                      ! cKN 2018/01/29
     &         jcoll .eq. 10 .or. jcoll .eq. 15 .or. jcoll .eq. 16 .or.
     &         jcoll .eq. 17 ) ) exit
         if( itout(m) .eq. 5 .and.                                      ! fission
     &       ( kcoll .eq. 1  .or. kcoll .eq. 5 ) ) exit
         if( itout(m) .eq. 6 .and.                                      ! absorption
     &       ( kcoll .eq. 2  .or. kcoll .eq. 6 ) ) exit
         if( itout(m) .eq. 7 .and. jcoll .eq. 5 ) exit                  ! heavyion
         if( itout(m) .eq. 8 .and. itrstar .eq. 0 ) exit                ! transmut, cKN 2015/06/29
         if( itout(m) .eq. 9 .and.                                      ! atomic, cABE 2017/02/08
     &       ( jcoll .eq. 11 .or. sum09 .gt. 0.d0 ) ) exit
         if( itout(m) .eq. 19 .and. jcoll .eq. 11 ) exit                ! deltaray, cABE 2018/02/27
         if( itout(m) .eq. 20 .and. sum20 .gt. 0.d0 ) exit              ! knockelec, cABE 2018/02/27
         if( itout(m) .eq. 21 .and. sum21 .gt. 0.d0 ) exit              ! atmflu
         if( itout(m) .eq. 22 .and. sum22 .gt. 0.d0 ) exit              ! auger
         if( itout(m) .eq. 23 .and. sum23 .gt. 0.d0 ) exit              ! brems
         if( itout(m) .eq. 24 .and. sum24 .gt. 0.d0 ) exit              ! photoelec
         if( itout(m) .eq. 25 .and. sum25 .gt. 0.d0 ) exit              ! compton
         if( itout(m) .eq. 26 .and. sum26 .gt. 0.d0 ) exit              ! pairprod
         if( itout(m) .eq. 27 .and. sum27 .gt. 0.d0 ) exit              ! annih
c Ogawa (2021/10/12) Ogawa renumber up to 99
         if( itout(m) .eq. 30 .and. sum30 .gt. 0.d0 ) exit              ! ets_elas
         if( itout(m) .eq. 31 .and. sum31 .gt. 0.d0 ) exit              ! ets_ioniz
         if( itout(m) .eq. 32 .and. sum32 .gt. 0.d0 ) exit              ! ets_e-exc
         if( itout(m) .eq. 33 .and. sum33 .gt. 0.d0 ) exit              ! ets_dea
         if( itout(m) .eq. 34 .and. sum34 .gt. 0.d0 ) exit              ! ets_v-exc
         if( itout(m) .eq. 35 .and. sum35 .gt. 0.d0 ) exit              ! ets_p-exc
         if( itout(m) .eq. 36 .and. sum36 .gt. 0.d0 ) exit              ! ets_r-exc
         if( itout(m) .eq. 37 .and. sum37 .gt. 0.d0 ) exit              ! ets_plasmon
         if( itout(m) .eq. 38 .and. sum38 .gt. 0.d0 ) exit              ! ets_ioniz_e-exc
         if( itout(m) .eq. 39 .and. sum39 .gt. 0.d0 ) exit              ! ets_hit
         if( itout(m) .eq. 40 .and. sum40 .gt. 0.d0 ) exit              ! kurbuc_elas
         if( itout(m) .eq. 41 .and. sum41 .gt. 0.d0 ) exit              ! kurbuc_ioniz
         if( itout(m) .eq. 42 .and. sum42 .gt. 0.d0 ) exit              ! kurbuc_e-exc
         if( itout(m) .eq. 43 .and. sum43 .gt. 0.d0 ) exit              ! kurbuc_e-cap
         if( itout(m) .eq. 44 .and. sum44 .gt. 0.d0 ) exit              ! kurbuc_e-stp
         if( itout(m) .eq. 48 .and. sum48 .gt. 0.d0 ) exit              ! kurbuc_ioniz_e-exc_e-cap
         if( itout(m) .eq. 49 .and. sum49 .gt. 0.d0 ) exit              ! kurbuc_hit
         if( itout(m) .eq. 50 .and. sum50 .gt. 0.d0 ) exit              ! its_elas
         if( itout(m) .eq. 51 .and. sum51 .gt. 0.d0 ) exit              ! its_ioniz
         if( itout(m) .eq. 52 .and. sum52 .gt. 0.d0 ) exit              ! its_e-exc
         if( itout(m) .eq. 58 .and. sum58 .gt. 0.d0 ) exit              ! its_ioniz_e-exc_e-cap
         if( itout(m) .eq. 59 .and. sum59 .gt. 0.d0 ) exit              ! its_hit

         if( itout(m) .eq. 96 .and. sum96 .gt. 0.d0 ) exit              ! ts_w
         if( itout(m) .eq. 97 .and. sum97 .gt. 0.d0 ) exit              ! ts_ioniz
         if( itout(m) .eq. 98 .and. sum98 .gt. 0.d0 ) exit              ! ts_ioniz_e-exc_e-cap
         if( itout(m) .eq. 99 .and. sum99 .gt. 0.d0 ) exit              ! ts_hit

         ichk = 0

      enddo

      if( ichk .eq. 0 ) return

*-----------------------------------------------------------------------
c for TTB count

      if( ( itout(m).eq.1 .or. itout(m).eq.9 .or. itout(m).eq.23 ) .and.
     &    ityp .ne. 12 .and. atmrc(2,5) .gt. 0.d0 ) then
         ittb = 1
      else
         ittb = 0
      endif

*-----------------------------------------------------------------------

      if( iMeVperu.eq.1 .and. ityp.ge.15 .and. ityp.le.19 ) then
           ebm = ktyp - ktyp / 1000000 * 1000000
      else
           ebm = 1.d0
      end if

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                jcount(i,1) .gt. itcnt(i*2+3,m) ) return

               end if

            end do

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        mother
*-----------------------------------------------------------------------

                ata   = dble( mathz + mathn )
                atz   = dble( mathz )
                mmas  = nint( ata )
                mchg  = nint( atz )

*-----------------------------------------------------------------------
*        for specific mother nuclei
*-----------------------------------------------------------------------

            if( nm .gt. 0 ) then

               do i = 1, nm

                  iz = mt(i) / 1000
                  ia = mt(i) - iz * 1000

                  if( ( ia .gt. 0 .and.
     &                  mmas .eq. ia .and. mchg .eq. iz ) .or.
     &                ( ia .eq. 0 .and. mchg .eq. iz ) ) then

                     if( itmct(m) .gt. 0 ) goto 140
                     if( itmct(m) .lt. 0 ) return

                  end if

               end do

                  if( itmct(m) .gt. 0 ) return

            end if

  140       continue

*-----------------------------------------------------------------------
*        check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

c for TTB by electron
            if( ittb .eq. 1 ) then
               call pcheck(m,np,12,11,-1,ipna,ipsa)
            else
               ipna = 0
               do i = 1, itmxpt    ! S.Abe 2022/06/29, 6 -> itmxpt
                  ipsa(i) = 0
               enddo
            endif
            ipnchk = ipn + ipna
            if( ipnchk .eq. 0 ) return

*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

            if( ec(ibkec+no,ipomp+1) .lt. eb(1)*ebm ) return
            if( ec(ibkec+no,ipomp+1) .ge. eb(ne+1)*ebm ) return

*-----------------------------------------------------------------------
*        check of time
*-----------------------------------------------------------------------

            tpart = abs(tc(ibktc+no,ipomp+1))

            if( tpart .lt. tb(1) ) return
            if( tpart .ge. tb(nt+1) ) return

*-----------------------------------------------------------------------
*        transform positions
*-----------------------------------------------------------------------

            call trnsxx(xc(ibkxc+no,ipomp+1),yc(ibkyc+no,ipomp+1),
     &                   zc(ibkzc+no,ipomp+1),
     &                  xxc,yyc,zzc,itmtr(m,4))

*-----------------------------------------------------------------------
*        check position : out of rainge
*-----------------------------------------------------------------------

            if(  xxc .lt. xm(1) ) return
            if(  xxc .ge. xm(nx+1) ) return

            if(  yyc .lt. ym(1) ) return
            if(  yyc .ge. ym(ny+1) ) return

            if(  zzc .lt. zm(1) ) return
            if(  zzc .ge. zm(nz+1) ) return

*-----------------------------------------------------------------------
*           x-position
*-----------------------------------------------------------------------

               do i = 1, nx

                  if( xxc .ge. xm(i) .and.
     &                xxc .lt. xm(i+1) ) goto 36

               end do

   36          ix1 = i

*-----------------------------------------------------------------------
*           y-position
*-----------------------------------------------------------------------

               do i = 1, ny

                  if( yyc .ge. ym(i) .and.
     &                yyc .lt. ym(i+1) ) goto 37

               end do

   37          iy1 = i

*-----------------------------------------------------------------------
*           z-position
*-----------------------------------------------------------------------

               do i = 1, nz

                  if( zzc .ge. zm(i) .and.
     &                zzc .lt. zm(i+1) ) goto 38

               end do

   38          iz1 = i

*-----------------------------------------------------------------------
*           energy
*-----------------------------------------------------------------------

            do i = 1, ne

               if( ec(ibkec+no,ipomp+1) .ge. eb(i)*ebm .and.
     &             ec(ibkec+no,ipomp+1) .lt. eb(i+1)*ebm ) goto 30

            end do

   30          ie1 = i

*-----------------------------------------------------------------------
*           time
*-----------------------------------------------------------------------

            do i = 1, nt

               if( tpart .ge. tb(i) .and.
     &             tpart .lt. tb(i+1) ) goto 50

            end do

   50          it1 = i

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------
cABE 2018/02/15, reconstruct

         actnum = 0.d0

         if( itout(m) .eq. 1 .or. itout(m) .eq. 9 ) then

            if( ityp .eq. 1 .or. ityp .ge. 15 ) then
               if( jcoll .eq. 11 ) actnum = 1.d0

            elseif( ityp .eq. 14 ) then
               actnum = atmrc(1,1) + atmrc(1,2) + atmrc(1,3)
     &                + atmrc(1,4) + atmrc(1,5)

            elseif( ityp .eq. 12 ) then
               actnum = atmrc(2,1) + atmrc(2,2) + atmrc(2,3)
     &                + atmrc(2,4) + atmrc(2,5)
     &                + atmrc(6,1) + atmrc(6,2) + atmrc(6,3)
     &                + atmrc(6,4) + atmrc(6,5) + atmrc(6,6)
     &                + atmrc(6,7)

            elseif( ityp .eq. 13 ) then
               actnum = atmrc(3,1) + atmrc(3,2) + atmrc(3,3)
     &                + atmrc(3,4) + atmrc(3,5)
     &                + atmrc(7,1) + atmrc(7,2) + atmrc(7,3)
     &                + atmrc(7,4) + atmrc(7,5) + atmrc(7,6)
     &                + atmrc(7,7)

            elseif( ityp .eq. 7 ) then
               actnum = atmrc(4,1) + atmrc(4,3) + atmrc(4,5)
               if( jcoll .eq. 11 ) actnum = actnum + 1.d0

            elseif( ityp .eq. 6 ) then
               actnum = atmrc(5,3) + atmrc(5,5)
               if( jcoll .eq. 11 ) actnum = actnum + 1.d0

            endif

            if( itout(m) .eq. 1 .and. actnum .le. 0.d0 ) actnum = 1.d0  ! not atomic reaction

*-----------------------------------------------------------------------

         elseif( itout(m) .ge. 19 ) then   ! S.Abe 2018/02/27, 20->19

            if( ityp .eq. 1 ) then
               Select Case( itout(m) )
                case(40)
                 actnum = atmrc(8,1)              ! kurbuc_elas
                case(41)
                 actnum = atmrc(8,2)              ! kurbuc_ioniz
                case(42)
                 actnum = atmrc(8,3)              ! kurbuc_e-exc
                case(43)
                 actnum = atmrc(8,4)              ! kurbuc_e-cap
                case(44)
                 actnum = atmrc(8,5)              ! kurbuc_e-stp
                case(48)
                 actnum = sum(atmrc(8,2:4))       ! kurbuc_ioniz_e-exc_e-cap
                case(49)
                 actnum = sum(atmrc(8,1:5))       ! kurbuc_hit

                case(50)
                 actnum = atmrc(10,1)             ! its_elas
                case(51)
                 actnum = atmrc(10,2)             ! its_ioniz
                case(52)
                 actnum = atmrc(10,3)             ! its_e-exc
                case(58)
                 actnum = atmrc(10,2) + atmrc(10,3)! its_ioniz_e-exc_e-cap
                case(59)
                 actnum = sum(atmrc(10,1:7))      ! its_hit

                case(96) 
                 actnum = atmrc(8,2) + atmrc(8,5) + atmrc(10,2)  ! ts_w
                case(97) 
                 actnum = atmrc(8,2) + atmrc(10,2)  ! ts_ioniz
                case(98) 
                 actnum = sum(atmrc(8,2:4)) + sum(atmrc(10,2:3)) ! ts_bio
                case(99)
                 actnum = sum(atmrc(8,1:5)) + sum(atmrc(10,1:7))  ! ts_hit
               End Select
               if( jcoll    .eq. 11 ) actnum = 1.d0   ! deltaray

            elseif( ktyp .eq. 6000012 ) then
               Select Case( itout(m) )
                case(40)
                 actnum = atmrc(9,1)              ! kurbuc_elas
                case(41)
                 actnum = atmrc(9,2)              ! kurbuc_ioniz
                case(42)
                 actnum = atmrc(9,3)              ! kurbuc_e-exc
                case(43)
                 actnum = atmrc(9,4)              ! kurbuc_e-cap
                case(44)
                 actnum = atmrc(9,5)              ! kurbuc_e-stp
                case(48)
                 actnum = sum(atmrc(9,2:4))       ! kurbuc_ioniz_e-exc_e-cap
                case(49)
                 actnum = sum(atmrc(9,1:5))       ! kurbuc_hit

                case(50)
                 actnum = atmrc(10,1)             ! its_elas
                case(51)
                 actnum = atmrc(10,2)             ! its_ioniz
                case(52)
                 actnum = atmrc(10,3)             ! its_e-exc
                case(58)
                 actnum = atmrc(10,2) + atmrc(10,3)! its_ioniz_e-exc_e-cap
                case(59)
                 actnum = sum(atmrc(10,1:7))      ! its_hit

                case(96) 
                 actnum = atmrc(9,2) + atmrc(10,2) + atmrc(9,5) ! ts_w
                case(97) 
                 actnum = atmrc(9,2) + atmrc(10,2) ! ts_ioniz
                case(98) 
                 actnum = sum(atmrc(9,2:4)) + sum(atmrc(10,2:3)) ! ts_bio
                case(99)
                 actnum = sum(atmrc(9,1:5))+sum(atmrc(10,1:7))  ! ts_hit
               End Select
               if( jcoll    .eq. 11 ) actnum = 1.d0   ! deltaray

            elseif( ityp .ge. 15 ) then
               Select Case( itout(m) )
                case(50)
                 actnum = atmrc(10,1)             ! its_elas
                case(51)
                 actnum = atmrc(10,2)             ! its_ioniz
                case(52)
                 actnum = atmrc(10,3)             ! its_e-exc
                case(58)
                 actnum = atmrc(10,2) + atmrc(10,3)! its_ioniz_e-exc_e-cap
                case(59)
                 actnum = sum(atmrc(10,1:7))      ! its_hit

                case(96) 
                 actnum = atmrc(10,2)             ! ts_w
                case(97) 
                 actnum = atmrc(10,2)             ! ts_ioniz
                case(98) 
                 actnum = sum(atmrc(10,2:3))      ! ts_bio
                case(99)
                 actnum = sum(atmrc(10,1:7))      ! ts_hit
               End Select

               if( jcoll    .eq. 11 ) actnum = 1.d0   ! deltaray

            elseif( ityp .eq. 14 ) then
              Select Case( itout(m) )
               case(21)
                actnum = atmrc(1,1)   ! atomic fluorescence
               case(22)
                actnum = atmrc(1,2)   ! auger
               case(24)
                actnum = atmrc(1,3)   ! photoelectric
               case(25)
                actnum = atmrc(1,4)   ! compton
               case(26)
                actnum = atmrc(1,5)   ! pairprod
               case(99)
                actnum = sum(atmrc(1,1:5))
              End Select

            elseif( ityp .eq. 12 ) then
              Select Case( itout(m) )
               case(21)
                actnum = atmrc(2,1)               ! atomic fluorescence
               case(22)
                actnum = atmrc(2,2)               ! auger
               case(23)
                actnum = atmrc(2,3) + atmrc(2,5)  ! bremsstrahlung
               case(20)
                actnum = atmrc(2,4)               ! knock-on
               case(30)
                actnum = atmrc(6,1)               ! ets_elas
               case(31)
                actnum = atmrc(6,2)               ! ets_ioniz
               case(32)
                actnum = atmrc(6,3)               ! ets_e-exc
               case(33)
                actnum = atmrc(6,4)               ! ets_dea
               case(34)
                actnum = atmrc(6,5)               ! ets_v-exc
               case(35)
                actnum = atmrc(6,6)               ! ets_p-exc
               case(36)
                actnum = atmrc(6,7)               ! ets_r-exc
               case(37)
                actnum = atmrc(6,8)               ! ets_r-exc
               case(38)
                actnum = atmrc(6,2) + atmrc(6,3)  ! ets_ioniz_e-exc
               case(39)
                actnum = sum(atmrc(6,1:7))        ! ets_hit
               case(96) 
                actnum = atmrc(6,2)               ! ts_w
               case(97) 
                actnum = atmrc(6,2)               ! ts_ioniz
               case(98) 
                actnum = atmrc(6,2) + atmrc(6,3) + atmrc(6,4) ! ts_bio
               case(99)
                actnum = sum(atmrc(6,1:7))        ! ts_hit
              End Select

            elseif( ityp .eq. 13 ) then
              Select Case( itout(m) )
               case(21)
                actnum = atmrc(3,1)               ! atomic fluorescence
               case(22)
                actnum = atmrc(3,2)               ! auger
               case(23)
                actnum = atmrc(3,3)               ! bremsstrahlung
               case(20)
                actnum = atmrc(3,4)               ! knock-on
               case(27)
                actnum = atmrc(3,5)               ! annihilation
               case(30)
                actnum = atmrc(7,1)               ! ets_elas
               case(31)
                actnum = atmrc(7,2)               ! ets_ioniz
               case(32)
                actnum = atmrc(7,3)               ! ets_e-exc
               case(33)
                actnum = atmrc(7,4)               ! ets_dea
               case(34)
                actnum = atmrc(7,5)               ! ets_v-exc
               case(35)
                actnum = atmrc(7,6)               ! ets_p-exc
               case(36)
                actnum = atmrc(7,7)               ! ets_r-exc
               case(37)
                actnum = atmrc(7,8)               ! ets_r-exc
               case(38)
                actnum = atmrc(7,2) + atmrc(7,3)  ! ets_ioniz_e-exc
               case(39)
                actnum = sum(atmrc(7,1:7))        ! ets_hit
               case(96) 
                actnum = atmrc(7,2)               ! ts_w
               case(97) 
                actnum = atmrc(7,2)               ! ts_ioniz
               case(98) 
                actnum = atmrc(7,2) + atmrc(7,3) + atmrc(7,4) ! ts_bio
               case(99)
                actnum = sum(atmrc(7,1:7))        ! ts_hit
              End Select

            elseif( ityp .eq. 7 ) then
               if( jcoll .eq. 11 ) actnum = 1.d0            ! deltaray
               if( itout(m) .eq. 21 ) actnum = atmrc(4,1)   ! atomic fluorescence
               if( itout(m) .eq. 23 ) actnum = atmrc(4,3)   ! bremsstrahlung
               if( itout(m) .eq. 26 ) actnum = atmrc(4,5)   ! pairprod

            elseif( ityp .eq. 6 ) then
               if( jcoll .eq. 11 ) actnum = 1.d0            ! deltaray
               if( itout(m) .eq. 23 ) actnum = atmrc(5,3)   ! bremsstrahlung
               if( itout(m) .eq. 26 ) actnum = atmrc(5,5)   ! pairprod

            endif

*-----------------------------------------------------------------------

         else

            actnum = 1.d0

         endif

*-----------------------------------------------------------------------

         tlw = oldwt * actnum

         do ip = 1, ipn

            trEVENT(ips(ip),ie1,it1,ix1,iy1,iz1) =
     &      trEVENT(ips(ip),ie1,it1,ix1,iy1,iz1) + tlw

         end do

*-----------------------------------------------------------------------
c for TTB count

         if( ipna .ne. 0 ) then

            tlw = oldwt * atmrc(2,5)

            do ip = 1, ipna
               trEVENT(ipsa(ip),ie1,it1,ix1,iy1,iz1) =
     &         trEVENT(ipsa(ip),ie1,it1,ix1,iy1,iz1) + tlw
            end do

         endif

*-----------------------------------------------------------------------

         call setitrminmax(itrmin,itrmax,2,6,
     &                     (/ie1,it1,ix1,iy1,iz1/))

*-----------------------------------------------------------------------
*        dump data on file
*-----------------------------------------------------------------------

         if( itmdp(m,0) .ne. 0 ) then
               dmpd(1)  = dble( ktyp )
               dmpd(2)  = xc(ibkxc+no,ipomp+1)
               dmpd(3)  = yc(ibkyc+no,ipomp+1)
               dmpd(4)  = zc(ibkzc+no,ipomp+1)
               dmpd(5)  = u(ibku+no,ipomp+1)
               dmpd(6)  = v(ibkv+no,ipomp+1)
               dmpd(7)  = w(ibkw+no,ipomp+1)
               dmpd(8)  = ec(ibkec+no,ipomp+1)
               dmpd(9)  = oldwt
               dmpd(10) = abs(tc(ibktc+no,ipomp+1))
               dmpd(11) = ncnt(ibknct+1,no,ipomp+1)
               dmpd(12) = ncnt(ibknct+2,no,ipomp+1)
               dmpd(13) = ncnt(ibknct+3,no,ipomp+1)
               dmpd(14) = spx(ibkspx+no,ipomp+1)
               dmpd(15) = spy(ibkspy+no,ipomp+1)
               dmpd(16) = spz(ibkspz+no,ipomp+1)
               dmpd(17) = name(ibknam+no,ipomp+1)
               dmpd(18) = nocas
               dmpd(19) = nobch
               dmpd(20) = no

               if( ipart .ge. 15 )
     &         dmpd(8) = dmpd(8) / ibryf(ipart,kpart)

            if(idmpomp.ne.0)then       !FURUTA20150427
             call writeompfile(m,dmpd) !FURUTA20150427
            else                       !FURUTA20150427

             if( itmdp(m,0) .gt. 0 ) then

               write(itmdf(m))
     &         ( dmpd(itmdp(m,k)), k = 1, abs( itmdp(m,0) ) )

              else

               write(itmdf(m),'(30(1p1d24.15))')
     &         ( dmpd(itmdp(m,k)), k = 1, abs( itmdp(m,0) ) )

              end if

            endif !FURUTA20150427

         end if

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine pstarxyz(m,np,nl,lt,
     &                    nx,ny,nz,ne,nt,xm,ym,zm,eb,tb,tr,
     &                    igsh,idasa)
*                                                                      *
*       output xyz scoring mesh star density tally                     *
*       last modified by K.Niita on 2004/12/27                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall28/ itgsh(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)
      common /tall49/ itglt(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /tcntl/  icntl, inucr

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   eb(ne+1)
      dimension   ew(ne)
      dimension   tb(nt+1)
      dimension   tw(nt)
      dimension   tr(np,ne,nt,nx,ny,nz,2)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

      dimension tott(np,2) ! frtati 2021/10/05 6 -> np

      character hsunit(12)*28

      data hsunit( 1) / '[1/cm^3/source]         '/
      data hsunit( 2) / '[1/cm^3/MeV/source]     '/
      data hsunit(11) / '[1/cm^3/nsec/source]    '/
      data hsunit(12) / '[1/cm^3/MeV/nsec/source]'/

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      character cha*1
      data cha /"'"/

      character dc2*4
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31

*-----------------------------------------------------------------------

      character rpa*1
      data rpa /'}'/
      character yen*1

*-----------------------------------------------------------------------

      integer :: itbmp
      common /tall63/ itbmp(itlmax)

      integer :: bmpWidth, bmpHeight
      character(1), allocatable :: bmpfIType(:)
      integer, allocatable :: bmpfIndex(:)
      integer :: numIndex

      integer :: itvtk, itvtkfmt
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      integer :: isunit_vtk_default = 91
      integer :: isunit_vtk_meta_default = 92
      integer :: isunit_vtk_rm_default = 93
      integer :: isunit_vtk_geom_default = 94
      integer :: isunit_vtk_geom_meta_default = 95
      integer :: iunit_vtk_g_default = 96
      integer :: isunit_vtk = 0
      integer :: isunit_vtk_meta = 0
      integer :: isunit_vtk_rm = 0
      integer :: isunit_vtk_geom = 0
      integer :: isunit_vtk_geom_meta = 0
      integer :: iunit_vtk_g = 0
      integer :: ios

      character(len=255) :: outFilename
      logical :: isText
      real(8),allocatable :: vl_x(:,:),vl_y(:,:),vl_z(:,:)

      include 'samepage_include/samepage000.inc'

*-----------------------------------------------------------------------
*        set mesh volume
*-----------------------------------------------------------------------

         vl(ix,iy,iz) = vls(nl,lt,itmcn(m),itvm(m),itmtr(m,4),
     &                      xm(ix),xm(ix+1),
     &                      ym(iy),ym(iy+1),
     &                      zm(iz),zm(iz+1))

      include 'samepage_include/samepage001.inc'

*-----------------------------------------------------------------------
! sumover
      allocate (vl_x(ny,nz),vl_y(nx,nz),vl_z(nx,ny))
      vl_x(:,:) = 0.0d0
      vl_y(:,:) = 0.0d0
      vl_z(:,:) = 0.0d0
      do iz = 1,nz
        do iy = 1,ny
           do ix = 1,nx
             vl_x(iy,iz) = vl_x(iy,iz) + vl(ix,iy,iz)
             vl_y(ix,iz) = vl_y(ix,iz) + vl(ix,iy,iz)
             vl_z(ix,iy) = vl_z(ix,iy) + vl(ix,iy,iz)
          enddo
        enddo
      enddo

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------

      if ( iMeVperu.eq. 1 ) then
         hsunit( 2) = '[1/cm^3/(MeV/n)/source]     '
         hsunit(12) = '[1/cm^3/(MeV/n)/nsec/source]'
      end if

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            neg = ne
            ntg = nt

         else

            npg = 1
            neg = 1
            ntg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1, 11 : /cm^2/source      /cm^2/nsec/source
*                    = 2, 12 : /cm^2/MeV/source  /cm^2/MeV/nsec/source
*-----------------------------------------------------------------------

            if( itunt(m) .eq. 1 .or. itunt(m) .eq. 11 ) then

               do i = 1, ne

                  ew(i) = 1.d+0

               end do
               ew_sum = 1.0d0

            else if( itunt(m) .eq. 2 .or. itunt(m) .eq. 12 ) then

               do i = 1, ne

                  ew(i) = eb(i+1) - eb(i)

               end do
               ew_sum = eb(ne+1) - eb(1)

            end if

*-----------------------------------------------------------------------
*           itunt(m) = 11, 12 : /.../nsec/source
*-----------------------------------------------------------------------

            if( itunt(m) .gt. 10 ) then

               do i = 1, nt

                  tw(i) = tb(i+1) - tb(i)

               end do
               tw_sum = tb(nt+1) - tb(1)

            else

               do i = 1, nt

                  tw(i) = 1.d+0

               end do
               tw_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

                  cmax = 0.0
                  cmin = 1.e+33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

         if( igsh .eq. 0 ) then

            if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

               c1 = 1.0d+0 / rsouin

            else

               c1 = 0d0

            end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

            do 101 iz = 1, nz
            do 101 iy = 1, ny
            do 101 ix = 1, nx
            do 101 it = 1, nt
            do 101 ie = 1, ne
            do 101 ip = 1, np

