************************************************************************
*                                                                      *
      subroutine tdpareg(ncol,m,nd,ns,np,nr,mr,nm,mt,nl,lt,kr,tr,
     &                   trEVENT)
*                                                                      *
*       dpa tally in region mesh                                       *
*            modified by K.Niita on 2005/01/13                         *
*       last modified by Y.Iwamoto on 2011/08/10                       *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
*        jcoll : =  0, nothing happen                                  *
*                =  1, Hydrogen collisions                             *
*                =  2, Particle Decays                                 *
*                =  3, Elastic collisions                              *
*                =  4, High Energy Nuclear collisions                  *
*                =  5, Heavy Ion reactions                             *
*                =  6, Neutron reactions by data                       *
*                =  7, Photon reactions by data                        *
*                =  8, Electron reactions by data                      *
*                =  9, P,d,a, and photo-nuclear reactions by data      *
*                = 10, Neutron event mode                              *
*                = 11, Delta Ray production                            *
*                = 12, Muon atomic interaction                         *
*                = 13, Photon by EGS5                                  *
*                = 14, Electron by EGS5                                *
*                = 15, Photon photonuclear interaction                 *
*                = 16, Negative muon captured by nucleon               *
*                = 17, Muon photonuclear interaction                   *
*                = 18, Electron recoil by track strcuture mode         *
*                = 19, Muon pair production (photon -> mu+ mu-)        *
*                = 20, User defined interaction                        *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*     definition of tr( nd, np, nr, id )                               *
*                                                                      *
*        ns = 1 : dpa, 2 : simple, 3 : all                             *
*                                                                      *
*      nd ..... number of event type                                   *
*        ns = 1                                                        *
*          1 : total dpa                                               *
*                                                                      *
*        ns = 2                                                        *
*          2 : cutoff1 produced particle at nuclear reaction           *
*          3 : cutoff2 transport particle                              *
*          4 : transport                                               *
*          5 : library                                                 *
*                                                                      *
*        ns = 3                                                        *
*          6 : deuteron                                                *
*          7 : triton                                                  *
*          8 : 3He                                                     *
*          9 : alpha                                                   *
*         10 : residual                                                *
*                                                                      *
*       id ..... data type                                             *
*          1 : dpa                                                     *
*          2 : relative error                                          *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
      use moddas_material
      use moddas_tally
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)
      common /mathzn/ mathz, mathn, jcoll, kcoll
!$OMP THREADPRIVATE(/mathzn/)
      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)
      common /regdc/  idrg(kvlmax), idgr(kvmmax)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall12/ itman(itlmax), itmat(itlmax), itmct(itlmax),
     &                itnun(itlmax), itnuc(itlmax),
     &                itndz(itlmax), itndn(itlmax),
     &                itnkz(itlmax), itnkn(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall33/ itln(itlmax,2), itli(itlmax,2), itlr(itlmax,2),
     &                rtdm(itlmax,2)
      common /tall37/ itcnt(9,itlmax)

      common /tall80/ itdpa(itlmax)
      common /tall81/ iteth(itlmax)

      common /tall82/ itcnth(9,itlmax)


*-----------------------------------------------------------------------

      common /kmat1g/ kmat(kvlmax)

*-----------------------------------------------------------------------

      dimension   mt(nm)
      dimension   lt(nl)
      dimension   kr(mr)
      dimension   tr(nd,np,nr,2)
      dimension   trEVENT(nd,np,nr)         !OBINATA(2012.9.13): as Ct
      real(8),allocatable,save:: tr0(:,:,:) !OBINATA(2012.9.13): as C

      dimension   sek(10)
      dimension   ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt

*-----------------------------------------------------------------------

      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas
*-----------------------------------------------------------------------

      real*8 edep
      common/EPCONTedep/ edep
!$OMP THREADPRIVATE(/EPCONTedep/)
      integer iegsemi, iegsout
      common /egsemi/ iegsemi, iegsout

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.13): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,1) = tr(:,:,:,1) + trEVENT(:,:,:)
             tr(:,:,:,2) = tr(:,:,:,2) + trEVENT(:,:,:) ** 2

           end if

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.13): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(nd,np,nr) )
             tr0(:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (tdpareg_crit_ist1)
             tr0(:,:,:) = tr0(:,:,:) + trEVENT(:,:,:)
!$OMP END CRITICAL (tdpareg_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,1) = tr(:,:,:,1) + tr0(:,:,:) / maxcas
             tr(:,:,:,2) = tr(:,:,:,2)
     &                     + ( tr0(:,:,:) / maxcas ) ** 2
             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol, ncol = 9, 10, 11, 12, 15
*        only for library neutron, proton and nucleus
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

         if( ( ( ncol .ge. 9 .and. ncol .le. 12 ) .or.
     &           ncol .eq. 15 ) .and.
     &       ityp .ne.  1 .and. ityp .ne.  2 .and.
     &       ityp .ne. 15 .and. ityp .ne. 16 .and.
     &       ityp .ne. 17 .and. ityp .ne. 18 .and.
     &       ityp .ne. 19 ) return

         if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &       ( jcoll .eq. 7 .or. jcoll .eq. 8 ) ) return

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( mat .le. 0 ) return

               lem = nint( dnel_das(kmat0+mat) )

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check of mat for library
*-----------------------------------------------------------------------

            libm = 0

*-----------------------------------------------------------------------

         if( ityp .eq. 1 .and.
     &       itln(m,1) .gt. 0 .and.
     &       e(ibke+no,ipomp+1) .lt. rtdm(m,1) ) then

               nlb = itln(m,1)

                  do i = 1, nlb

                     if( idmn(mat) .eq. mlib(itli(m,1),i) ) then

                        libm = mlib(itli(m,1)+1,i)
                        mtid = mlib(itli(m,1)+2,i)

                        goto 503

                     end if

                  end do

                  if( jcoll .gt. 5 .and. jcoll .ne. 9 ) return

  503          continue

         end if

*-----------------------------------------------------------------------

         if( ityp .eq. 2 .and.
     &       itln(m,2) .gt. 0 .and.
     &       e(ibke+no,ipomp+1) .lt. rtdm(m,2) ) then

               nlb = itln(m,2)

                  do i = 1, nlb

                     if( idmn(mat) .eq. mlib(itli(m,2),i) ) then

                        libm = mlib(itli(m,2)+1,i)
                        mtid = mlib(itli(m,2)+2,i)

                        goto 504

                     end if

                  end do

                  if( jcoll .gt. 5 .and. jcoll .ne. 10 ) return

  504          continue

         end if

*-----------------------------------------------------------------------
*        for specific mother nuclei only for reaction part
*        T.Sato 2025/03/05, not necessary to be checked here
*-----------------------------------------------------------------------

!         if( libm .eq. 0 .and. ncol .ne. 11 .and.
!     &       ( jcoll .le. 5  .or. jcoll .eq. 10 .or.
!     &         jcoll .eq. 12 .or.
!     &         jcoll .eq. 16 .or. jcoll .eq. 17 ) ) then   ! S.Abe 2017/01/17
!
!                  ata   = dble( mathz + mathn )
!                  atz   = dble( mathz )
!                  mmas  = nint( ata )
!                  mchg  = nint( atz )
!                if( nm .gt. 0 ) then
!
!                  do i = 1, nm
!
!                     iz = mt(i) / 1000
!                     ia = mt(i) - iz * 1000
!
!                     if( ( ia .gt. 0 .and.
!     &                     mmas .eq. ia .and. mchg .eq. iz ) .or.
!     &                   ( ia .eq. 0 .and. mchg .eq. iz ) ) then
!
!                        if( itmct(m) .gt. 0 ) goto 140
!                        if( itmct(m) .lt. 0 ) return
!
!                     end if
!
!                  end do
!
!                     if( itmct(m) .gt. 0 ) return
!
!               end if
!
!  140       continue
!
!
!         end if

*-----------------------------------------------------------------------
*        check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 ) return

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

                  jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir1 = ii

*-----------------------------------------------------------------------
*     dpa tally
*-----------------------------------------------------------------------

      if( ( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &      ( jcoll .le. 5  .or. jcoll .eq. 10 .or.
     &        jcoll .eq. 12 .or.
     &        jcoll .eq. 16 .or. jcoll .eq. 17 ) ) .or.   ! S.Abe 2017/01/17
     &    ityp .eq.  1 .or. ityp .eq. 15 .or.
     &    ityp .eq. 16 .or. ityp .eq. 17 .or.
     &        ityp .eq. 18 .or. ityp .eq. 19 .or.
     &        ityp .eq.  3 .or. ityp .eq.  5 .or.
     &        ityp .eq.  6 .or. ityp .eq.  7 .or.
     &        ityp .eq.  8 .or. ityp .eq. 10 .or.
     &        ityp .eq.  12 .or. ityp .eq. 13 ) then

*-----------------------------------------------------------------------
*     dpa tally for reactions and transport charged particles
*-----------------------------------------------------------------------

                  sekd = 0.0

               do i = 1, 10
                  sek(i) = 0.0
               end do

*-----------------------------------------------------------------------

         do 300 k = 1, lem + 1

                  if( k .le. lem ) then

                     itz = nint( zz_das(kmat(mat)+k) )
                     ita = nint( a_das(kmat(mat)+k) )
                     dns = den_das(kmat(mat)+k)

                  else

                     ita = 1
                     itz = 1
                     dns = denh_das(kmat0+mat)

                  end if

                     if( dns .le. 0.0d0 ) goto 300

                  a2  = ita
                  z2  = itz

               sekd = sekd + dns ! T.Sato 2025/03/05 must be calculated before checking mother

            if( nm .gt. 0 ) then

               do i = 1, nm

                  iz = mt(i) / 1000
                  ia = mt(i) - iz * 1000

                  if( ( ia .gt. 0 .and.
     &                  ita .eq. ia .and. itz .eq. iz ) .or.
     &                ( ia .eq. 0 .and. itz .eq. iz ) ) then

                     if( itmct(m) .gt. 0 ) goto 200
                     if( itmct(m) .lt. 0 ) goto 300

                  end if

               end do

                  if( itmct(m) .gt. 0 ) goto 300

  200          continue

            end if

!              sekd = sekd + dns  ! Original location, but this causes strange result

*-----------------------------------------------------------------------
*           nuclear reaction ( no library )
*-----------------------------------------------------------------------

            if( libm .eq. 0 .and.
     &          ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &          ( jcoll .le. 5  .or. jcoll .eq. 10 .or.
     &            jcoll .eq. 12 .or.
     &            jcoll .eq. 16 .or. jcoll .eq. 17 ) ) then   ! S.Abe 2017/01/17

               if( nclsts .gt. 0 ) then

*-----------------------------------------------------------------------
*              check of counter for produced particles
*-----------------------------------------------------------------------

               do i = 1, 3

                  if( itcnt(i,m) .ne. 0 ) then

                     if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                   jcount(i,1) .gt. itcnt(i*2+3,m) ) goto 400

                  end if

               end do

*-----------------------------------------------------------------------

                  do j = 1, nclsts

                        ipart = jclusts(3,j)

                     if( jclusts(4,j) .lt. 0 .and.
     &                   ipart .ge. 15 .and. ipart .le. 19) then

                        ext = qclusts(7,j)
                        cwt = qclusts(8,j)
                        a1  = jclusts(1,j) + jclusts(2,j)
                        z1  = jclusts(1,j)

*-----------------------------------------------------------------------
*                    local approximation
*                    dpab = damage cross section(cm2)
*                         * traveling length (cm)
*-----------------------------------------------------------------------

                        e1 = ext
                        e2 = 0

                        iityp = jclusts(3,j)
                        kktyp = jclusts(7,j)
                        jjtyp = jclusts(5,j)
                        rrtyp = qclusts(5,j) * 1.0d+3

			idpa = itdpa(m)
			ieth = iteth(m)
                        call dpal3(mat,iityp,kktyp,jjtyp,rrtyp,
     &                             z1,a1,z2,a2,dpab,e1,e2,idpa,ieth)

cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

                        dpae = dpab * dns * cwt

                        sek(1) = sek(1) + dpae
                        sek(2) = sek(2) + dpae

                        if( iityp .ge. 15 .and. iityp .le. 19 ) then

                           sek(iityp-9) = sek(iityp-9) + dpae

                        end if

                     end if

                  end do

               end if

            end if

  400       continue

*-----------------------------------------------------------------------

*-----------------------------------------------------------------------
*           check of counter for transport particle
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                           goto 300

               end if

            end do

*-----------------------------------------------------------------------
*           stopped proton and nucleus
*-----------------------------------------------------------------------

            if( ncol .eq. 11 .and. jtyp .ne. 0 ) then

                     ext = ec(ibkec+no,ipomp+1)
                     a1  = dble( mtyp )
                     z1  = dble( jtyp )

*-----------------------------------------------------------------------
*                 local approximation
*                 dpa = damage cross section(cm2)
*                     * traveling length (cm)
*-----------------------------------------------------------------------

                     e1 = ext
                     e2 = 0

			idpa = itdpa(m)
			ieth = iteth(m)
                  call dpal3(mat,ityp,ktyp,jtyp,rtyp,
     &                       z1,a1,z2,a2,dpab,e1,e2,idpa,ieth)

                        dpae = dpab * dns * oldwt

                        sek(1) = sek(1) + dpae
                        sek(3) = sek(3) + dpae

                     if( ityp .ge. 15 .and. ityp .le. 19 ) then

                        sek(ityp-9) = sek(ityp-9) + dpae

                     end if

            end if

*-----------------------------------------------------------------------
*           transport charged particles
*-----------------------------------------------------------------------

            if( jtyp .ne. 0 .and. ec(ibkec+no,ipomp+1) .lt.
     &                             e(ibke+no,ipomp+1) ) then

                     e1 = e(ibke+no,ipomp+1)
                     e2 = ec(ibkec+no,ipomp+1)
                     a1 = dble( mtyp )
                     z1 = dble( jtyp )

*-----------------------------------------------------------------------
*                 local approximation
*                 dpa = damage cross section(cm2)
*                     * traveling length (cm)
*-----------------------------------------------------------------------
			idpa = itdpa(m)
			ieth = iteth(m)
                  call dpal3(mat,ityp,ktyp,jtyp,rtyp,
     &                       z1,a1,z2,a2,dpab,e1,e2,idpa,ieth)

                        dpae = dpab * dns * oldwt

                        sek(1) = sek(1) + dpae
                        sek(4) = sek(4) + dpae

                     if( ityp .ge. 15 .and. ityp .le. 19 ) then

                        sek(ityp-9) = sek(ityp-9) + dpae

                     end if

            end if

*-----------------------------------------------------------------------

  300    continue

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

         if( sekd .gt. 0.0 ) then

               do i = 1, 10

                  sek(i) = sek(i) / sekd

               end do

                  do ip = 1, ipn

                     trEVENT(1,ips(ip),ir1) =
     &               trEVENT(1,ips(ip),ir1) + sek(1)

                  end do

            if( ns .eq. 2 ) then

               do i = 2, 4
                  do ip = 1, ipn

                     trEVENT(i,ips(ip),ir1) =
     &               trEVENT(i,ips(ip),ir1) + sek(i)

                  end do
               end do

            else if( ns .eq. 3 ) then

               do i = 2, 10
                  do ip = 1, ipn

                     trEVENT(i,ips(ip),ir1) =
     &               trEVENT(i,ips(ip),ir1) + sek(i)

                  end do
               end do

            end if

         end if

*-----------------------------------------------------------------------

      end if

*-----------------------------------------------------------------------
*     dpa tally for library
*-----------------------------------------------------------------------

      if( libm .gt. 0 ) then

*-----------------------------------------------------------------------
*           check of counter for transport particle
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                                        goto 100

               end if

            end do

*-----------------------------------------------------------------------

            lma = idnm( libm )
            icl = idgr( iblz1 )
            erf = ( e(ibke+no,ipomp+1) + ec(ibkec+no,ipomp+1) ) / 2.0
            tgt = sqrt( ( xc(ibkxc+no,ipomp+1) - x(ibkx+no,ipomp+1) )**2
     &                + ( yc(ibkyc+no,ipomp+1) - y(ibky+no,ipomp+1) )**2
     &              + ( zc(ibkzc+no,ipomp+1) - z(ibkz+no,ipomp+1) )**2 )

               call getcrs(ityp,icl,erf,lma,mtid,dpanf,0)

               dpanl = dpanf * tgt * oldwt * 1.0d+24

                     do ip = 1, ipn

                        trEVENT(1,ips(ip),ir1) =
     &                  trEVENT(1,ips(ip),ir1) + dpanl

                     end do

               if( ns .ge. 2 ) then
                     do ip = 1, ipn

                        trEVENT(5,ips(ip),ir1) =
     &                  trEVENT(5,ips(ip),ir1) + dpanl

                     end do
               end if

      end if

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine tdpatet(ncol,m,nd,ns,np,nr,mr,nm,mt,nl,lt,tr,kr,
     &                   trEVENT)
*                                                                      *
*       dpa tally in tetra mesh                                        *
*       Last Modified by T.Furuta on 2025/01/16                        *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
*        jcoll : =  0, nothing happen                                  *
*                =  1, Hydrogen collisions                             *
*                =  2, Particle Decays                                 *
*                =  3, Elastic collisions                              *
*                =  4, High Energy Nuclear collisions                  *
*                =  5, Heavy Ion reactions                             *
*                =  6, Neutron reactions by data                       *
*                =  7, Photon reactions by data                        *
*                =  8, Electron reactions by data                      *
*                =  9, P,d,a, and photo-nuclear reactions by data      *
*                = 10, Neutron event mode                              *
*                = 11, Delta Ray production                            *
*                = 12, Muon atomic interaction                         *
*                = 13, Photon by EGS5                                  *
*                = 14, Electron by EGS5                                *
*                = 15, Photon photonuclear interaction                 *
*                = 16, Negative muon captured by nucleon               *
*                = 17, Muon photonuclear interaction                   *
*                = 18, Electron recoil by track strcuture mode         *
*                = 19, Muon pair production (photon -> mu+ mu-)        *
*                = 20, User defined interaction                        *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*     definition of tr( nd, np, nr, id )                               *
*                                                                      *
*        ns = 1 : dpa, 2 : simple, 3 : all                             *
*                                                                      *
*      nd ..... number of event type                                   *
*        ns = 1                                                        *
*          1 : total dpa                                               *
*                                                                      *
*        ns = 2                                                        *
*          2 : cutoff1 produced particle at nuclear reaction           *
*          3 : cutoff2 transport particle                              *
*          4 : transport                                               *
*          5 : library                                                 *
*                                                                      *
*        ns = 3                                                        *
*          6 : deuteron                                                *
*          7 : triton                                                  *
*          8 : 3He                                                     *
*          9 : alpha                                                   *
*         10 : residual                                                *
*                                                                      *
*       id ..... data type                                             *
*          1 : dpa                                                     *
*          2 : relative error                                          *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
      use moddas_material
      use moddas_tally
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)
      common /mathzn/ mathz, mathn, jcoll, kcoll
!$OMP THREADPRIVATE(/mathzn/)
      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)
      common /regdc/  idrg(kvlmax), idgr(kvmmax)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall12/ itman(itlmax), itmat(itlmax), itmct(itlmax),
     &                itnun(itlmax), itnuc(itlmax),
     &                itndz(itlmax), itndn(itlmax),
     &                itnkz(itlmax), itnkn(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall33/ itln(itlmax,2), itli(itlmax,2), itlr(itlmax,2),
     &                rtdm(itlmax,2)
      common /tall37/ itcnt(9,itlmax)

      common /tall80/ itdpa(itlmax)
      common /tall81/ iteth(itlmax)

      common /tall82/ itcnth(9,itlmax)


*-----------------------------------------------------------------------

      common /kmat1g/ kmat(kvlmax)

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   mt(nm)
      dimension   lt(nl)
      dimension   tr(nd,np,nr,2)
      dimension   trEVENT(nd,np,nr)         !OBINATA(2012.9.13): as Ct
      real(8),allocatable,save:: tr0(:,:,:) !OBINATA(2012.9.13): as C

      dimension   sek(10)
      dimension   ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt

*-----------------------------------------------------------------------

      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas
*-----------------------------------------------------------------------

      real*8 edep
      common/EPCONTedep/ edep
!$OMP THREADPRIVATE(/EPCONTedep/)
      integer iegsemi, iegsout
      common /egsemi/ iegsemi, iegsout

      integer iii0,kkk0
      common /itettal2/ iii0,kkk0
!$OMP THREADPRIVATE(/itettal2/)

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.13): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,1) = tr(:,:,:,1) + trEVENT(:,:,:)
             tr(:,:,:,2) = tr(:,:,:,2) + trEVENT(:,:,:) ** 2

           end if

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.13): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(nd,np,nr) )
             tr0(:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (tdpatet_crit_ist1)
             tr0(:,:,:) = tr0(:,:,:) + trEVENT(:,:,:)
!$OMP END CRITICAL (tdpatet_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,1) = tr(:,:,:,1) + tr0(:,:,:) / maxcas
             tr(:,:,:,2) = tr(:,:,:,2)
     &                     + ( tr0(:,:,:) / maxcas ) ** 2
             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol, ncol = 9, 10, 11, 12, 15
*        only for library neutron, proton and nucleus
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

         if( ( ( ncol .ge. 9 .and. ncol .le. 12 ) .or.
     &           ncol .eq. 15 ) .and.
     &       ityp .ne.  1 .and. ityp .ne.  2 .and.
     &       ityp .ne. 15 .and. ityp .ne. 16 .and.
     &       ityp .ne. 17 .and. ityp .ne. 18 .and.
     &       ityp .ne. 19 ) return

         if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &       ( jcoll .eq. 7 .or. jcoll .eq. 8 ) ) return

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( mat .le. 0 ) return

               lem = nint( dnel_das(kmat0+mat) )

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check of mat for library
*-----------------------------------------------------------------------

            libm = 0

*-----------------------------------------------------------------------

         if( ityp .eq. 1 .and.
     &       itln(m,1) .gt. 0 .and.
     &       e(ibke+no,ipomp+1) .lt. rtdm(m,1) ) then

               nlb = itln(m,1)

                  do i = 1, nlb

                     if( idmn(mat) .eq. mlib(itli(m,1),i) ) then

                        libm = mlib(itli(m,1)+1,i)
                        mtid = mlib(itli(m,1)+2,i)

                        goto 503

                     end if

                  end do

                  if( jcoll .gt. 5 .and. jcoll .ne. 9 ) return

  503          continue

         end if

*-----------------------------------------------------------------------

         if( ityp .eq. 2 .and.
     &       itln(m,2) .gt. 0 .and.
     &       e(ibke+no,ipomp+1) .lt. rtdm(m,2) ) then

               nlb = itln(m,2)

                  do i = 1, nlb

                     if( idmn(mat) .eq. mlib(itli(m,2),i) ) then

                        libm = mlib(itli(m,2)+1,i)
                        mtid = mlib(itli(m,2)+2,i)

                        goto 504

                     end if

                  end do

                  if( jcoll .gt. 5 .and. jcoll .ne. 10 ) return

  504          continue

         end if

*-----------------------------------------------------------------------
*        check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 ) return

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

               jj = 0

               ic=idgr(iblz1)
               itet=kkk0-10000
               ihelem=iii0

               call ttetck(ic,mr,kr,itet,ihelem,ir1,icc)

               if( icc .ne. 1 ) goto 100

*-----------------------------------------------------------------------
*     dpa tally
*-----------------------------------------------------------------------

      if( ( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &      ( jcoll .le. 5  .or. jcoll .eq. 10 .or.
     &        jcoll .eq. 12 .or.
     &        jcoll .eq. 16 .or. jcoll .eq. 17 ) ) .or.   ! S.Abe 2017/01/17
     &    ityp .eq.  1 .or. ityp .eq. 15 .or.
     &    ityp .eq. 16 .or. ityp .eq. 17 .or.
     &        ityp .eq. 18 .or. ityp .eq. 19 .or.
     &        ityp .eq.  3 .or. ityp .eq.  5 .or.
     &        ityp .eq.  6 .or. ityp .eq.  7 .or.
     &        ityp .eq.  8 .or. ityp .eq. 10 .or.
     &        ityp .eq.  12 .or. ityp .eq. 13 ) then

*-----------------------------------------------------------------------
*     dpa tally for reactions and transport charged particles
*-----------------------------------------------------------------------

                  sekd = 0.0

               do i = 1, 10
                  sek(i) = 0.0
               end do

*-----------------------------------------------------------------------

         do 300 k = 1, lem + 1

                  if( k .le. lem ) then

                     itz = nint( zz_das(kmat(mat)+k) )
                     ita = nint( a_das(kmat(mat)+k) )
                     dns = den_das(kmat(mat)+k)

                  else

                     ita = 1
                     itz = 1
                     dns = denh_das(kmat0+mat)

                  end if

                     if( dns .le. 0.0d0 ) goto 300

                  a2  = ita
                  z2  = itz

               sekd = sekd + dns ! T.Sato 2025/03/05 must be calculated before checking mother

            if( nm .gt. 0 ) then

               do i = 1, nm

                  iz = mt(i) / 1000
                  ia = mt(i) - iz * 1000

                  if( ( ia .gt. 0 .and.
     &                  ita .eq. ia .and. itz .eq. iz ) .or.
     &                ( ia .eq. 0 .and. itz .eq. iz ) ) then

                     if( itmct(m) .gt. 0 ) goto 200
                     if( itmct(m) .lt. 0 ) goto 300

                  end if

               end do

                  if( itmct(m) .gt. 0 ) goto 300

  200          continue

            end if

*-----------------------------------------------------------------------
*           nuclear reaction ( no library )
*-----------------------------------------------------------------------

            if( libm .eq. 0 .and.
     &          ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &          ( jcoll .le. 5  .or. jcoll .eq. 10 .or.
     &            jcoll .eq. 12 .or.
     &            jcoll .eq. 16 .or. jcoll .eq. 17 ) ) then   ! S.Abe 2017/01/17

               if( nclsts .gt. 0 ) then

*-----------------------------------------------------------------------
*              check of counter for produced particles
*-----------------------------------------------------------------------

               do i = 1, 3

                  if( itcnt(i,m) .ne. 0 ) then

                     if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                   jcount(i,1) .gt. itcnt(i*2+3,m) ) goto 400

                  end if

               end do

*-----------------------------------------------------------------------

                  do j = 1, nclsts

                        ipart = jclusts(3,j)

                     if( jclusts(4,j) .lt. 0 .and.
     &                   ipart .ge. 15 .and. ipart .le. 19) then

                        ext = qclusts(7,j)
                        cwt = qclusts(8,j)
                        a1  = jclusts(1,j) + jclusts(2,j)
                        z1  = jclusts(1,j)

*-----------------------------------------------------------------------
*                    local approximation
*                    dpab = damage cross section(cm2)
*                         * traveling length (cm)
*-----------------------------------------------------------------------

                        e1 = ext
                        e2 = 0

                        iityp = jclusts(3,j)
                        kktyp = jclusts(7,j)
                        jjtyp = jclusts(5,j)
                        rrtyp = qclusts(5,j) * 1.0d+3



			idpa = itdpa(m)
			ieth = iteth(m)
                        call dpal3(mat,iityp,kktyp,jjtyp,rrtyp,
     &                             z1,a1,z2,a2,dpab,e1,e2,idpa,ieth)

cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

                        dpae = dpab * dns * cwt

                        sek(1) = sek(1) + dpae
                        sek(2) = sek(2) + dpae

                        if( iityp .ge. 15 .and. iityp .le. 19 ) then

                           sek(iityp-9) = sek(iityp-9) + dpae

                        end if

                     end if

                  end do

               end if

            end if

  400       continue

*-----------------------------------------------------------------------

*-----------------------------------------------------------------------
*           check of counter for transport particle
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                                                goto 300

               end if

            end do

*-----------------------------------------------------------------------
*           stopped proton and nucleus
*-----------------------------------------------------------------------

            if( ncol .eq. 11 .and. jtyp .ne. 0 ) then

                     ext = ec(ibkec+no,ipomp+1)
                     a1  = dble( mtyp )
                     z1  = dble( jtyp )

*-----------------------------------------------------------------------
*                 local approximation
*                 dpa = damage cross section(cm2)
*                     * traveling length (cm)
*-----------------------------------------------------------------------

                     e1 = ext
                     e2 = 0

			idpa = itdpa(m)
			ieth = iteth(m)
                  call dpal3(mat,ityp,ktyp,jtyp,rtyp,
     &                       z1,a1,z2,a2,dpab,e1,e2,idpa,ieth)

                        dpae = dpab * dns * oldwt

                        sek(1) = sek(1) + dpae
                        sek(3) = sek(3) + dpae

                     if( ityp .ge. 15 .and. ityp .le. 19 ) then

                        sek(ityp-9) = sek(ityp-9) + dpae

                     end if

            end if

*-----------------------------------------------------------------------
*           transport charged particles
*-----------------------------------------------------------------------

            if( jtyp .ne. 0 .and. ec(ibkec+no,ipomp+1) .lt.
     &                e(ibke+no,ipomp+1) ) then

                     e1 = e(ibke+no,ipomp+1)
                     e2 = ec(ibkec+no,ipomp+1)
                     a1 = dble( mtyp )
                     z1 = dble( jtyp )

*-----------------------------------------------------------------------
*                 local approximation
*                 dpa = damage cross section(cm2)
*                     * traveling length (cm)
*-----------------------------------------------------------------------
			idpa = itdpa(m)
			ieth = iteth(m)
                  call dpal3(mat,ityp,ktyp,jtyp,rtyp,
     &                       z1,a1,z2,a2,dpab,e1,e2,idpa,ieth)

                        dpae = dpab * dns * oldwt

                        sek(1) = sek(1) + dpae
                        sek(4) = sek(4) + dpae

                     if( ityp .ge. 15 .and. ityp .le. 19 ) then

                        sek(ityp-9) = sek(ityp-9) + dpae

                     end if

            end if

*-----------------------------------------------------------------------

  300    continue

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

         if( sekd .gt. 0.0 ) then

               do i = 1, 10

                  sek(i) = sek(i) / sekd

               end do

                  do ip = 1, ipn

                     trEVENT(1,ips(ip),ir1) =
     &               trEVENT(1,ips(ip),ir1) + sek(1)

                  end do

            if( ns .eq. 2 ) then

               do i = 2, 4
                  do ip = 1, ipn

                     trEVENT(i,ips(ip),ir1) =
     &               trEVENT(i,ips(ip),ir1) + sek(i)

                  end do
               end do

            else if( ns .eq. 3 ) then

               do i = 2, 10
                  do ip = 1, ipn

                     trEVENT(i,ips(ip),ir1) =
     &               trEVENT(i,ips(ip),ir1) + sek(i)

                  end do
               end do

            end if

         end if

*-----------------------------------------------------------------------

      end if

*-----------------------------------------------------------------------
*     dpa tally for library
*-----------------------------------------------------------------------

      if( libm .gt. 0 ) then

*-----------------------------------------------------------------------
*           check of counter for transport particle
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                                goto 100

               end if

            end do

*-----------------------------------------------------------------------

            lma = idnm( libm )
            icl = idgr( iblz1 )
            erf = ( e(ibke+no,ipomp+1) + ec(ibkec+no,ipomp+1) ) / 2.0
            tgt = sqrt( ( xc(ibkxc+no,ipomp+1) - x(ibkx+no,ipomp+1) )**2
     &                + ( yc(ibkyc+no,ipomp+1) - y(ibky+no,ipomp+1) )**2
     &              + ( zc(ibkzc+no,ipomp+1) - z(ibkz+no,ipomp+1) )**2 )

               call getcrs(ityp,icl,erf,lma,mtid,dpanf,0)

               dpanl = dpanf * tgt * oldwt * 1.0d+24

                     do ip = 1, ipn

                        trEVENT(1,ips(ip),ir1) =
     &                  trEVENT(1,ips(ip),ir1) + dpanl

                     end do

               if( ns .ge. 2 ) then
                     do ip = 1, ipn

                        trEVENT(5,ips(ip),ir1) =
     &                  trEVENT(5,ips(ip),ir1) + dpanl

                     end do
               end if

      end if

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine pdpareg(m,nd,ns,np,nr,mr,kr,tr,nvl,ivl,rvl,
     &                   nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the dpa tally in region mesh                            *
*       last modified by K.Niita on 2004/09/15                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

      common /tall21/ rtfac(itlmax)

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /volreg/ dvol(kvlmax)
      common /regdc/  idrg(kvlmax), idgr(kvmmax)

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   tr(nd,np,nr,2)
      dimension   ivl(nvl)
      dimension   rvl(nvl)

      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

      character hsunit(2)*20

      data hsunit / 'DPA [x1.E-24/source]',
     &              'DPA [1/source]      '/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chm moved to partmod

      character cht(10)*8

      data cht /'tot DPA ','cutoff1 ','cutoff2 ','transpt ','library ',
     &          'deuteron','tritium ','3Helium ','alpha   ',
     &          'Nuclei  '/

cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31


      character rpa*1
      data rpa /'}'/
      character yen*1

      include 'samepage_include/samepage000.inc'

      include 'samepage_include/samepage001.inc'

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            ndg = nd

         else

            npg = 1
            ndg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1 : DPA * 1.E-24/source
*                    = 2 : DPA/source
*-----------------------------------------------------------------------

            if( itunt(m) .eq. 1 ) then

               dnor = 1.0

            else if( itunt(m) .eq. 2 ) then

               dnor = 1.d+24

            end if

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

            do 101 ir = 1, nr
            do 101 ip = 1, np
            do 101 ik = 1, nd

               if( tr(ik,ip,ir,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ik,ip,ir,1) / dnor / vl(ir)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            do 100 ir = 1, nr
            do 100 ip = 1, np
            do 100 ik = 1, nd

               if( tr(ik,ip,ir,1) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ik,ip,ir,1),
     &                            tr(ik,ip,ir,2),
     &             abs(rtfac(m)/facmax(m))/dnor/vl(ir))

                  tr(ik,ip,ir,1) = Xa
                  tr(ik,ip,ir,2) = sigx
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ik,ip,ir,1) .gt. cmax )
     &                        cmax = tr(ik,ip,ir,1)

                  if( tr(ik,ip,ir,1) .lt. cmin )
     &                        cmin = tr(ik,ip,ir,1)

               else

                  isdz = 1
                  tr(ik,ip,ir,2) = 0.0

               end if

  100       continue

