************************************************************************

************************************************************************
*                                                                      *
      subroutine ttimereg_sumover(m,maxcas,
     &                   np,  ne, nt,  nr, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nr,2)                                            *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call ttimereg_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nr,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrgn_sum(m,iax),
     &     tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ttimereg_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nr, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,2)

      if(itaxs_in == 1) then  ! energ
        do ir = 1,nr
        do it = 1,nt
        do ip = 1,np
          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir) / maxcas
          end do
          tr_sum(ip,1,it,ir,1) =
     &           tr_sum(ip,1,it,ir,1) + tr0_sum
          tr_sum(ip,1,it,ir,2) =
     &          tr_sum(ip,1,it,ir,2) + tr0_sum ** 2
        end do
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do it = 1,nt
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ir = 1,nr
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir) / maxcas
          end do
          tr_sum(ip,ie,it,1,1) =
     &           tr_sum(ip,ie,it,1,1) + tr0_sum
          tr_sum(ip,ie,it,1,2) =
     &           tr_sum(ip,ie,it,1,2) + tr0_sum ** 2
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do ir = 1,nr
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do it = 1,nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir) / maxcas
          end do
          tr_sum(ip,ie,1,ir,1) =
     &           tr_sum(ip,ie,1,ir,1) + tr0_sum
          tr_sum(ip,ie,1,ir,2) =
     &          tr_sum(ip,ie,1,ir,2) + tr0_sum ** 2
        end do
        end do
        end do

       end if
       return
       end



************************************************************************
*                                                                      *
      subroutine ttimerz_sumover(m,maxcas,
     &                   np,  ne, nt,  nr, nz, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nr,nz,2)                                         *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr,nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call ttimerz_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nr, nz,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrnm_sum(m,iax),itznm_sum(m,iax),
     &     tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ttimerz_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nr, nz, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr,nz)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nz_sum,2)

      if(itaxs_in == 1) then  ! energ
        do iz = 1, nz
        do ir = 1, nr
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,1,it,ir,iz,1) =
     &           tr_sum(ip,1,it,ir,iz,1) + tr0_sum
          tr_sum(ip,1,it,ir,iz,2) =
     &          tr_sum(ip,1,it,ir,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
!

      elseif(itaxs_in == 5) then    ! z
        do ir = 1, nr
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iz = 1, nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,it,ir,1,1) =
     &           tr_sum(ip,ie,it,ir,1,1) + tr0_sum
          tr_sum(ip,ie,it,ir,1,2) =
     &           tr_sum(ip,ie,it,ir,1,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 6) then    ! r
        do iz = 1, nz
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ir = 1, nr
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,it,1,iz,1) =
     &           tr_sum(ip,ie,it,1,iz,1) + tr0_sum
          tr_sum(ip,ie,it,1,iz,2) =
     &           tr_sum(ip,ie,it,1,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do iz = 1, nz
        do ir = 1, nr
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,1,ir,iz,1) =
     &           tr_sum(ip,ie,1,ir,iz,1) + tr0_sum
          tr_sum(ip,ie,1,ir,iz,2) =
     &          tr_sum(ip,ie,1,ir,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine ttimexyz_sumover(m,maxcas,
     &                   np,  ne, nt,  nx, ny, nz, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nx,ny,nz,2)                                   *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nx,ny,nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call ttimexyz_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nx, ny, nz,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &     tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine ttimexyz_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nx, ny, nz, tr0,
     &           np_sum,  ne_sum, nt_sum, nx_sum, ny_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nx,ny,nz)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,2)

      if(itaxs_in == 1) then  ! energ
        do iz = 1, nz
        do iy = 1, ny
        do ix = 1, nx
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ix,iy,iz) / maxcas
          end do
          tr_sum(ip,1,it,ix,iy,iz,1) =
     &           tr_sum(ip,1,it,ix,iy,iz,1) + tr0_sum
          tr_sum(ip,1,it,ix,iy,iz,2) =
     &          tr_sum(ip,1,it,ix,iy,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 3) then    ! x
        do iz = 1, nz
        do iy = 1, ny
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ix = 1, nx
            tr0_sum = tr0_sum + tr0(ip,ie,it,ix,iy,iz) / maxcas
          end do
          tr_sum(ip,ie,it,1,iy,iz,1) =
     &           tr_sum(ip,ie,it,1,iy,iz,1) + tr0_sum
          tr_sum(ip,ie,it,1,iy,iz,2) =
     &           tr_sum(ip,ie,it,1,iy,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 4) then    ! y
        do iz = 1, nz
        do ix = 1, nx
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iy = 1, ny
            tr0_sum = tr0_sum + tr0(ip,ie,it,ix,iy,iz) / maxcas
          end do
          tr_sum(ip,ie,it,ix,1,iz,1) =
     &           tr_sum(ip,ie,it,ix,1,iz,1) + tr0_sum
          tr_sum(ip,ie,it,ix,1,iz,2) =
     &           tr_sum(ip,ie,it,ix,1,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 5) then    ! z
        do iy = 1, ny
        do ix = 1, nx
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iz = 1, nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,ix,iy,iz) / maxcas
          end do
          tr_sum(ip,ie,it,ix,iy,1,1) =
     &           tr_sum(ip,ie,it,ix,iy,1,1) + tr0_sum
          tr_sum(ip,ie,it,ix,iy,1,2) =
     &           tr_sum(ip,ie,it,ix,iy,1,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do iz = 1, nz
        do iy = 1, ny
        do ix = 1, nx
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ix,iy,iz) / maxcas
          end do
          tr_sum(ip,ie,1,ix,iy,iz,1) =
     &           tr_sum(ip,ie,1,ix,iy,iz,1) + tr0_sum
          tr_sum(ip,ie,1,ix,iy,iz,2) =
     &          tr_sum(ip,ie,1,ix,iy,iz,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine ptimereg_sumover_stdev(mode,m,ip,ie,it,ir,
     &                fact_in,ew,tw,vm,ew_sum,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)
     
      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
        endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/ew/tw/vm
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vm / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call ptimereg_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ir,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrgn_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
