        endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/ew/tw/vm
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vm / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call ptimereg_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ir,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrgn_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ptimereg_sumover_stdev_sub(mode,m,sum_fact,
     &                   ip,ie,it,ir,
     &                   np_sum,ne_sum,nt_sum,nr_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,2)
      
      if(tr_sum(ip,ie,it,ir,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,ir,1),
     &                  tr_sum(ip,ie,it,ir,2),
     &                  sum_fact)
        else
          sum_fact_r = 1.0d0 / sum_fact
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,ir,1),
     &                  tr_sum(ip,ie,it,ir,2),
     &                  sum_fact_r)
        endif

        tr_sum(ip,ie,it,ir,1) = Xa
        tr_sum(ip,ie,it,ir,2) = sigx

      else

        tr_sum(ip,ie,it,ir,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  ptimereg_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,ntstepi,nrstepi,
     &    ipi,iei,iti,iri,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

          call ptimereg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,
     &    ipi,iei,iti,iri,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrgn_sum(m,iax),
     &    tr_sum)

       else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * ntstepi * nrstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call ptimereg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,
     &    ipi,iei,iti,iri,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrgn_sum(m,iax),
     &    tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine ptimereg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,
     &    ipi,iei,iti,iri,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nr_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nt_sum,nr_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
           do irloop=1,nrstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                iri+irloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                iri+irloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do

      return
      end


