************************************************************************
*                                                                      *
      subroutine ptime_star_xyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,iti,ixi,iyi,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
         do izloop=1,nzstepi
          do iyloop=1,nystepi
           do ixloop=1,nxstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do
         end do
        end do

      return
      end


************************************************************************
*                                                                      *
      subroutine tstarreg_sumover(m,maxcas,
     &                   np,  ne, nt,  nr, nact, tr0x,ldo)
*                                                                      *
*     tr_sum(np,ne,nt,nr,nact,2)                                       *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr,nact)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      dimension ldo(2,*)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call tstarreg_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nr, nact,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrgn_sum(m,iax),itactnm_sum(m,iax),
     &     tr_sum,ldo)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine tstarreg_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nr, nact, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum, nact_sum,
     &           tr_sum,ldo)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension ldo(2,*)
      dimension   tr0(np,ne,nt,nr,nact)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nact_sum,2)

      if(itaxs_in == 1) then  ! energ
        do iact = ldo(1,5), ldo(2,5)
        do ir = ldo(1,4), ldo(2,4)
        do it = ldo(1,3), ldo(2,3)
        do ip = ldo(1,1), ldo(2,1)
          tr0_sum = 0.0d0
          do ie = ldo(1,2), ldo(2,2)
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iact) / maxcas
          end do
          tr_sum(ip,1,it,ir,iact,1) =
     &           tr_sum(ip,1,it,ir,iact,1) + tr0_sum
          tr_sum(ip,1,it,ir,iact,2) =
     &          tr_sum(ip,1,it,ir,iact,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do iact = ldo(1,5), ldo(2,5)
        do it = ldo(1,3), ldo(2,3)
        do ie = ldo(1,2), ldo(2,2)
        do ip = ldo(1,1), ldo(2,1)
          tr0_sum = 0.0d0
          do ir = ldo(1,4), ldo(2,4)
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iact) / maxcas
          end do
          tr_sum(ip,ie,it,1,iact,1) =
     &           tr_sum(ip,ie,it,1,iact,1) + tr0_sum
          tr_sum(ip,ie,it,1,iact,2) =
     &           tr_sum(ip,ie,it,1,iact,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do iact = ldo(1,5), ldo(2,5)
        do ir = ldo(1,4), ldo(2,4)
        do ie = ldo(1,2), ldo(2,2)
        do ip = ldo(1,1), ldo(2,1)
          tr0_sum = 0.0d0
          do it = ldo(1,3), ldo(2,3)
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iact) / maxcas
          end do
          tr_sum(ip,ie,1,ir,iact,1) =
     &           tr_sum(ip,ie,1,ir,iact,1) + tr0_sum
          tr_sum(ip,ie,1,ir,iact,2) =
     &          tr_sum(ip,ie,1,ir,iact,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 12) then   ! act
        do ir = ldo(1,4), ldo(2,4)
        do it = ldo(1,3), ldo(2,3)
        do ie = ldo(1,2), ldo(2,2)
        do ip = ldo(1,1), ldo(2,1)
          tr0_sum = 0.0d0
          do iact = ldo(1,5), ldo(2,5)
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iact) / maxcas
          end do
          tr_sum(ip,ie,it,ir,1,1) =
     &           tr_sum(ip,ie,it,ir,1,1) + tr0_sum
          tr_sum(ip,ie,it,ir,1,2) =
     &          tr_sum(ip,ie,it,ir,1,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine tstarreg_sumover_tr(m,maxcas,
     &                   np,  ne, nt,  nr, nact, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nr,nact,2)                                       *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr,nact,2)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call tstarreg_sumover_sub_tr(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nr, nact,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrgn_sum(m,iax),itactnm_sum(m,iax),
     &     tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine tstarreg_sumover_sub_tr(maxcas,itaxs_in,
     &           np,  ne, nt, nr, nact, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum, nact_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr,nact,2)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nact_sum,2)
      dimension tr0_sum(2)

      if(itaxs_in == 1) then  ! energ
        do iact = 1, nact
        do ir = 1, nr
        do it = 1, nt
        do ip = 1, np
          tr0_sum(:) = 0.0d0
          do k=1,2
            do ie = 1, ne
              tr0_sum(k) = tr0_sum(k) + tr0(ip,ie,it,ir,iact,k)
            end do
            tr_sum(ip,1,it,ir,iact,k) = tr0_sum(k)
          enddo
        end do
        end do
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do iact = 1, nact
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum(:) = 0.0d0
          do k=1,2
            do ir = 1, nr
              tr0_sum(k) = tr0_sum(k) + tr0(ip,ie,it,ir,iact,k)
            end do
            tr_sum(ip,ie,it,1,iact,k) = tr0_sum(k)
          enddo
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do iact = 1, nact
        do ir = 1, nr
        do ie = 1, ne
        do ip = 1, np
          tr0_sum(:) = 0.0d0
          do k=1,2
            do it = 1, nt
              tr0_sum(k) = tr0_sum(k) + tr0(ip,ie,it,ir,iact,k)
            end do
            tr_sum(ip,ie,1,ir,iact,k) = tr0_sum(k)
          enddo
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 12) then   ! act
        do ir = 1, nr
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum(:) = 0.0d0
          do k=1,2
            do iact = 1, nact
              tr0_sum(k) = tr0_sum(k) + tr0(ip,ie,it,ir,iact,k)
            end do
            tr_sum(ip,ie,it,ir,1,k) = tr0_sum(k)
          enddo
        end do
        end do
        end do
        end do

       end if
       return
       end

